CREATE TABLE `case_items` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Case title',
  `region_id` bigint NOT NULL COMMENT 'Related region ID',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'culture_creative/animation_short/education/office_efficiency/software_dev/ecommerce_marketing/other',
  `actor_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Person, company or project name',
  `source_id` bigint NOT NULL COMMENT 'Main source ID',
  `summary` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Case summary',
  `business_model` text COLLATE utf8mb4_unicode_ci COMMENT 'Business model',
  `ai_tools` text COLLATE utf8mb4_unicode_ci COMMENT 'AI tools or capabilities',
  `outcome` text COLLATE utf8mb4_unicode_ci COMMENT 'Outcome or effect',
  `tags` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Comma separated tags',
  `original_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Original URL',
  `local_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Local file name',
  `accessed_at` date NOT NULL COMMENT 'Access or download date',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT 'draft/reviewed/published',
  `reviewer` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Reviewer',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Created time',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Updated time',
  PRIMARY KEY (`id`),
  KEY `idx_case_items_region_id` (`region_id`),
  KEY `idx_case_items_source_id` (`source_id`),
  KEY `idx_case_items_category` (`category`),
  KEY `idx_case_items_status` (`status`),
  KEY `idx_case_items_accessed_at` (`accessed_at`)
) ENGINE=InnoDB AUTO_INCREMENT=95 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Case item table';
