INSERT INTO `case_items` VALUES (3,'OPC生态森林正在生长！这里何以让创意青年“一个人战斗”？',32,'动漫短剧','壹笑（漫界工场创始人）',52,'壹笑从福建搬到苏州相城，入驻南艺·元和塘大学生文创园相关OPC生态。她以三国题材动漫为例，说明借助AI工具后，年轻创作者可以单兵完成动漫制作，把过去需要数月的工作压缩到更短周期，并围绕动漫创作链条寻找社区内协作伙伴。','地区：江苏省 / 苏州市 / 相城区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-01-26','AI工具；剧本生成；视觉设计；自动分发；自动化分镜；智能生成场景','时间效率提升10倍以上；一天能做1—2分钟成片；制作成本降低70%','动漫短剧,AI工具,剧本生成,视觉设计,自动分发,自动化分镜,智能生成场景','http://www.js.xinhuanet.com/20260126/293109e5e55d45bfa14c37522c23ba94/c.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(4,'OPC创业者们，苏州相城高新区邀你来造梦！',32,'智能零售','给物人文（苏州）科技有限公司',53,'给物人文（苏州）科技有限公司在苏州人工智能产业园打造9㎡ coffee店，以AI和具身机器人支撑咖啡即时零售。项目通过机械臂完成取杯、接取浓缩咖啡和拉花，唯一员工主要负责物料补充与设备巡检，验证单人管理复杂零售流程的可能性。','地区：江苏省 / 苏州市 / 相城区\n案例类型：智能零售\n是否为大学生创新创业：否\n发布日期：2025-12-18','AI+具身机器人；机械臂','仅需要一个人即可实现从点单、拉花制作到配送的全链条咖啡即时零售交互服务','智能零售,AI+具身机器人,机械臂','https://js.ifeng.com/c/8uBiUrb7meM',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(5,'“AI合伙人”给力，一人公司释放更多潜能',32,'自媒体','Joyce',54,'“00后”自媒体人Joyce使用AI工具提升公众号稿件生产效率，并可配套生成图片、视频等产品。她将原本的副业逐步转为主业，注册自然人独资公司探索OPC，通过AI承担部分内容生产工作，个人主要负责选题、判断和创业经营。','地区：江苏省 / 苏州市 / 工业园区\n案例类型：自媒体\n是否为大学生创新创业：否\n发布日期：2026-02-13','AI工具；图片；视频','写一篇公众号文章由至少半天缩短到不到两小时；收入增长迅速','自媒体,AI工具,图片,视频','http://jsjjb.xhby.net/pc/con/202602/13/content_1530765.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(6,'“AI合伙人”给力，一人公司释放更多潜能',32,'动漫短剧','李瑛',54,'“95后”漫剧师李瑛从杭州一家制作公司离职后，回到镇江开设OPC。报道中她将OPC视为远离职场焦虑、投入更多时间创作的方式，强调一人公司给创作者带来的自主节奏和创作空间。原文未进一步列明她使用的具体AI工具或经营数据。','地区：江苏省 / 镇江市 / 无明确区县\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-02-13',NULL,NULL,'动漫短剧','http://jsjjb.xhby.net/pc/con/202602/13/content_1530765.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(7,'海州“花果山下”系列OPC全面发力 点燃“一人+AI”创业新引擎',32,'办公效率','王丽霞',55,'王丽霞是花果山下·人工智能OPC社区创业者。她在社区协助下完成营业执照注册与入驻，并研发“企业运营智能体”。报道显示，她的智能体开发进入实测阶段，随后研发落地，体现个人借助人工智能方向社区资源推进企业运营工具开发。','地区：江苏省 / 连云港市 / 海州区\n案例类型：办公效率\n是否为大学生创新创业：否\n发布日期：2026-04-24','智能体；企业运营智能体','半天完成营业执照注册与社区入驻；短短2个月“企业运营智能体”研发落地','办公效率,智能体,企业运营智能体','http://www.lyg.gov.cn/zglygzfmhwz/fwzx_cycx/content/4f3fcde0-24ac-49f5-9e1c-3b68c80a8644.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(8,'海州“花果山下”系列OPC全面发力 点燃“一人+AI”创业新引擎',32,'智慧安防','胡宗义（江苏华域空天低空综合服务有限公司）',55,'江苏华域空天低空综合服务有限公司负责人胡宗义是人工智能OPC社区首批入驻创业者。报道中他表示，入驻后专利获批，罂粟巡查大模型投入使用；其项目围绕低空安防和大模型应用，在社区算力与服务体系支持下推进成长。','地区：江苏省 / 连云港市 / 海州区\n案例类型：智慧安防\n是否为大学生创新创业：否\n发布日期：2026-04-24','罂粟巡查大模型；悟空智算；大模型训练；AI视觉应用','入驻几个月专利成功获批；罂粟巡查大模型正式投入使用','智慧安防,罂粟巡查大模型,悟空智算,大模型训练,AI视觉应用','http://www.lyg.gov.cn/zglygzfmhwz/fwzx_cycx/content/4f3fcde0-24ac-49f5-9e1c-3b68c80a8644.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(9,'海州“花果山下”系列OPC全面发力 点燃“一人+AI”创业新引擎',32,'电商营销','刘杭坤',55,'“00后”创业者刘杭坤入驻花果山下·数智电商OPC社区后开展直播电商创业。社区围绕AI直播、智能办公和新媒体运营提供运营指导，并对接受众定位、直播IP打造、脚本策划、实时调控、数据复盘等环节，帮助他快速打开市场。','地区：江苏省 / 连云港市 / 海州区\n案例类型：电商营销\n是否为大学生创新创业：否\n发布日期：2026-04-24','AI直播；智能办公；新媒体运营；脚本策划；实时调控；数据复盘','开播首月直播间营业额突破15万元','电商营销,AI直播,智能办公,新媒体运营,脚本策划,实时调控,数据复盘','http://www.lyg.gov.cn/zglygzfmhwz/fwzx_cycx/content/4f3fcde0-24ac-49f5-9e1c-3b68c80a8644.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(10,'海州“花果山下”系列OPC全面发力 点燃“一人+AI”创业新引擎',32,'动漫短剧','丰睿',55,'丰睿从传统影视转向AIGC赛道，入驻花果山下·悟空智画OPC社区。他通过社区课程和“悟空AI”工作流学习AI漫剧制作方法，掌握AI高效创作流程后，用个人能力推进AI漫剧成片生产。','地区：江苏省 / 连云港市 / 海州区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-04-24','AIGC；AI高效创作方法；悟空AI工作流','一天能完成5分钟AI漫剧成片；商业项目成本直降85%；首批15家入驻企业拿下3部漫剧商业订单','动漫短剧,AIGC,AI高效创作方法,悟空AI工作流','http://www.lyg.gov.cn/zglygzfmhwz/fwzx_cycx/content/4f3fcde0-24ac-49f5-9e1c-3b68c80a8644.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(11,'上城鸿鹄汇重新定义AI时代创业新范式',33,'建筑设计','胡政涛',56,'建筑师出身的胡政涛以独立开发者身份构建AI原生3D建筑设计平台。他带着一台电脑和项目入驻鸿鹄汇，核心工作方式是一人、一电脑、一创意，并借助生成式AI跑通产品设计、开发到运营的闭环，AI助手成为其工作协同对象。','地区：浙江省 / 杭州市 / 上城区\n案例类型：建筑设计\n是否为大学生创新创业：否\n发布日期：2025-12-18','AI原生的3D建筑设计平台；生成式AI；AI助手','10个月写下14万行代码；获得5万美元启动资金；产品DEMO分享后引发行业关注','建筑设计,AI原生的3D建筑设计平台,生成式AI,AI助手','https://www.hangzhou.gov.cn/col/col812264/art/2025/art_790ac3062e7c411abd17db2f7bacabb6.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(12,'台州首个OPC社区正式运营',33,'视频制作','洪显鹏（台州鹏友佳文化科技有限公司）',57,'台州鹏友佳文化科技有限公司负责人洪显鹏作为首批入驻台州梦想园区OPC社区的创业者之一，承接AI视频制作相关项目。报道中他表示，入驻短短几天就对接了好几个AI视频制作项目，为二季度业务开了好头。','地区：浙江省 / 台州市 / 台州湾新区\n案例类型：视频制作\n是否为大学生创新创业：否\n发布日期：2026-05-05','AI视频制作','短短几天对接好几个AI视频制作项目；首批10家公司集中入驻并获颁营业执照','视频制作,AI视频制作','http://zj.people.com.cn/n2/2026/0505/c186327-41571380.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(13,'探访杭州“一人公司”：“工具是杠杆，想法才是支点”',33,'软件开发','祝鹤槐（聚身之家、采了么）',58,'祝鹤槐借助AI搜集信息、搭建机器人产销信息对接网站，后又用AI开发“采了么”APP，匹配人力帮助企业完成数据采集。他的工作方式是个人提出想法、AI放大效率，并用AI长期计划自动采集信息、解读反馈和定期复盘。','地区：浙江省 / 杭州市 / 上城区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-03-23','AI搜集信息；AI搭建网站；AI开发“采了么”APP；自动采集信息；AI复盘','获得3笔订单','软件开发,AI搜集信息,AI搭建网站,AI开发“采了么”APP,自动采集信息,AI复盘','http://zj.people.com.cn/n2/2026/0323/c228592-41531254.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(14,'探访杭州“一人公司”：“工具是杠杆，想法才是支点”',33,'动漫短剧','庞昊洋',58,'庞昊洋在杭州余杭良渚“数栖湾”AI+产业社区主攻“AI+短剧”。他的“硅基团队”由十几个AI组成，分别承担写剧本、画面生成和后期等任务，个人围绕AI协同完成短剧创业中的创意组织和业务推进。','地区：浙江省 / 杭州市 / 余杭区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-03-23','AI+短剧；写剧本；画面生成；后期','自2025年1月公司成立至今，营收达到一百多万元','动漫短剧,AI+短剧,写剧本,画面生成,后期','http://zj.people.com.cn/n2/2026/0323/c228592-41531254.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(15,'探访杭州“一人公司”：“工具是杠杆，想法才是支点”',33,'健康服务','张宸宇（安特易小程序）',58,'张宸宇创业方向为“AI+健康”，打造“安特易”小程序，为康复师和有居家康复训练需求的患者提供线上训练平台。该产品通过系统化定制管理居家康复训练；他的团队有三人，其中开发工作主要由AI承担。','地区：浙江省 / 杭州市 / 无明确区县\n案例类型：健康服务\n是否为大学生创新创业：否\n发布日期：2026-03-23','AI+健康；AI开发','2026年1月小程序上线；注册用户达到两三百人；70%的开发工作由AI完成','健康服务,AI+健康,AI开发','http://zj.people.com.cn/n2/2026/0323/c228592-41531254.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(16,'探访杭州“一人公司”：“工具是杠杆，想法才是支点”',33,'软件开发','徐铭泽（ANX AI原生应用交互协议）',58,'徐铭泽在AI大模型“豆包”推荐下来到杭州上城“中国数谷·未来数智港”，研发“ANX AI原生应用交互协议”。该协议把传统网页“翻译”成AI适读的样子，使AI在更少交互次数下获取更多信息，并与祝鹤槐的机器人之家网站形成业务互补。','地区：浙江省 / 杭州市 / 上城区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-03-23','AI大模型“豆包”；ANX AI原生应用交互协议',NULL,'软件开发,AI大模型“豆包”,ANX AI原生应用交互协议','http://zj.people.com.cn/n2/2026/0323/c228592-41531254.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(17,'上城区全省率先发布“一人公司”专项政策',33,'软件开发','赵若兰（杭州狂想启诺科技有限公司）',59,'赵若兰回到杭州创业后入驻上城区鸿鹄汇创业社区，创办杭州狂想启诺科技有限公司，开发个人成长APP“向着目标”。她的团队只有两个人，开发环节大量交由AI完成；她主要向AI提出需求，再由AI实现代码和功能。','地区：浙江省 / 杭州市 / 上城区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-03-04','AI工具辅助编程；AI写代码','个人成长APP“向着目标”已上线；AI承担80%的工作量；七八天功能开发缩短为一天；每月算力成本200到400美元','软件开发,AI工具辅助编程,AI写代码','https://www.hzsc.com.cn/content/content_9881063.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(18,'一人如何成军？走进中关村“一人公司”',11,'工业智能化','韩家乐（北京素源矩阵科技有限公司）',60,'韩家乐在美国学习和工作后，回国创立北京素源矩阵科技有限公司，聚焦“AI for Materials×工业智能化”。他独立搭建“AI+材料工艺”的模型和产品架构，并用大模型、代码工具和自动化工作流承担报告梳理、需求拆解、脚本编写、反馈收集、竞品分析和复盘等职能。','地区：北京市 / 北京市 / 海淀区\n案例类型：工业智能化\n是否为大学生创新创业：否\n发布日期：2026-05-07','工业AI大脑；大模型；代码工具；自动化工作流','不到三年完成从技术验证到产业落地；团队从1人扩展至7人；年营收从不足10万元增长至近千万元','工业智能化,工业AI大脑,大模型,代码工具,自动化工作流','http://kw.beijing.gov.cn/ztzl/rdzt/kjrmt/202605/t20260507_4639782.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(19,'OPC创业生态观察：北京海淀的“超级个体”与“热带雨林”',11,'办公效率','卢选君（北京卯智能科技有限责任公司）',61,'卢选君有10年UI/UX设计经验，在中关村AI北纬社区创办北京卯智能科技有限责任公司，开发Ascendant AI·主权分身系统。该系统在用户设备本地运行，通过工作经历、兴趣偏好和人生经验等信息建立个人数字分身，并以跨会话记忆提供连贯的个性化建议。','地区：北京市 / 北京市 / 海淀区\n案例类型：办公效率\n是否为大学生创新创业：否\n发布日期：2026-03-23','Ascendant AI·主权分身系统；本地运行大模型；跨会话记忆；智能体设计服务','计划先用20个种子用户打磨产品','办公效率,Ascendant AI·主权分身系统,本地运行大模型,跨会话记忆,智能体设计服务','http://dianzibao.cb.com.cn/images/2026-03/23/11/2644B07B.pdf',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(20,'模数OPC社区在北京亦庄落地 首批迎来20个创业团队入驻',11,'动漫短剧','北京整活视界科技有限公司',62,'北京整活视界科技有限公司是模数OPC社区首批入驻企业之一，聚焦AI影像作品创作。报道列举其作品《赛博鹏哥》和《第三次未命名项目》的传播与入围情况，作为社区AI视频生成与AIGC内容创作方向的代表案例。','地区：北京市 / 北京市 / 北京经济技术开发区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-04-08','AI影像作品；AI视频生成；AIGC内容创作','《赛博鹏哥》全网播放量超百万；《第三次未命名项目》入围2025釜山国际电影节ACFM单元、上海AI短片电影展','动漫短剧,AI影像作品,AI视频生成,AIGC内容创作','http://bj.people.com.cn/n2/2026/0408/c14540-41546648.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(21,'模数OPC社区在北京亦庄落地 首批迎来20个创业团队入驻',11,'动漫短剧','最最科技（北京）有限公司',62,'最最科技（北京）有限公司是模数OPC社区首批入驻企业之一，属于AI视频生成与AIGC内容创作生态中的企业案例。报道中列明其在AI影视领域获得机构荣誉、作品亮相海外活动并获得国际AI影视奖项。','地区：北京市 / 北京市 / 北京经济技术开发区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-04-08','AI视频生成；AIGC内容创作；AI影视','获第八届初心榜“十大AI引领机构”；作品亮相柏林电影节、大阪世博会；获海南岛国际电影节AI单元大奖、首尔国际AI电影节特别奖','动漫短剧,AI视频生成,AIGC内容创作,AI影视','http://bj.people.com.cn/n2/2026/0408/c14540-41546648.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(22,'模数OPC社区在北京亦庄落地 首批迎来20个创业团队入驻',11,'文化创意','九块积木',62,'九块积木是模数OPC社区首批入驻企业之一，打造AI IP“朱牛马”。报道将其作为AI视频与视觉设计工坊、AIGC内容创作方向的案例，重点呈现该IP在全网粉丝和内容播放上的传播表现。','地区：北京市 / 北京市 / 北京经济技术开发区\n案例类型：文化创意\n是否为大学生创新创业：否\n发布日期：2026-04-08','AI IP；AIGC内容创作','AI IP“朱牛马”全网粉丝超20万；累计播放量突破5000万次','文化创意,AI IP,AIGC内容创作','http://bj.people.com.cn/n2/2026/0408/c14540-41546648.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(23,'文汇报：一个人就是一支队伍！上海首个人工智能广告“一人公司”诞生！',31,'广告创意','野仙仙',63,'个人创作者野仙仙凭作品《AI心跳 超级有AI》获得2025AI广告品牌创新设计大赛案例类银奖后，在徐汇区市场监管局帮办服务下完成公司设立，成为上海首个人工智能广告OPC实践者。她规划专注品牌广告影片定位传播与创意制作，聚焦高端AIGC广告影片赛道。','地区：上海市 / 上海市 / 徐汇区\n案例类型：广告创意\n是否为大学生创新创业：否\n发布日期：2025-12-23','AI视觉生成；智能叙事；AIGC技术','获2025AI广告品牌创新设计大赛案例类银奖；从获奖到创业落地用时一个半月','广告创意,AI视觉生成,智能叙事,AIGC技术','https://scjgj.sh.gov.cn/603/20251223/2c984a729a0b6239019b49210c135094.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(24,'上海OPC生态：“六边形战士”集结',31,'软件开发','构序科技（丁军滔、宋海鑫共同创建）',64,'1997年出生的中科大硕士丁军滔与师弟宋海鑫在张江双子塔创建OPC构序科技，主打AI剪辑软件，目标是帮助视频创作者“用一句话剪出一条片子”。报道强调他们面向视频编辑需求，以OPC形式进入AI剪辑赛道。','地区：上海市 / 上海市 / 浦东新区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-05-04','AI剪辑软件；用一句话剪出一条片子',NULL,'软件开发,AI剪辑软件,用一句话剪出一条片子','http://sh.people.com.cn/BIG5/n2/2026/0504/c134768-41570914.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(25,'上海OPC生态：“六边形战士”集结',31,'文化创意','刘奕秀（茁野创意工作室）',64,'刘奕秀2024年4月离职后成立茁野创意工作室，独自经历创业初期，后来入驻静安“视听静界·π空间”OPC创新社区“派客家”。她将网页、App、音视频、小程序、礼盒、IP盲盒、公仔、陶艺等作为文创载体，并以项目协作方式寻找同类OPC伙伴。','地区：上海市 / 上海市 / 静安区\n案例类型：文化创意\n是否为大学生创新创业：否\n发布日期：2026-05-04','AI工具','两年内跑了50多家工厂；入驻后获得中国家电及消费电子博览会免费展示机会','文化创意,AI工具','http://sh.people.com.cn/BIG5/n2/2026/0504/c134768-41570914.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(26,'上海OPC生态：“六边形战士”集结',31,'教育培训','孔祥宇',64,'孔祥宇辞去美国工作后，决定聚焦“AI+教育”赛道创办OPC。报道中，他曾比较不同城市的科创人才政策，最终被上海浦东国际人才港小程序中清晰的申请流程、对接人和联系电话吸引，体现其围绕AI教育方向选择创业落点。','地区：上海市 / 上海市 / 浦东新区\n案例类型：教育培训\n是否为大学生创新创业：否\n发布日期：2026-05-04','AI+教育',NULL,'教育培训,AI+教育','http://sh.people.com.cn/BIG5/n2/2026/0504/c134768-41570914.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(27,'OPC | 一个人注册公司 一群人合作项目——95后海归的OPC创业实验',31,'文化创意','蔡正琨（钧正数创）',65,'蔡正琨是动态影像专业海归，2025年回到上海并注册成立钧正数创。他以OPC方式经营数智创意设计、品牌传播与文化出海等业务，个人负责概念构思、设计创作和项目统筹，并按项目调动工艺师、IT开发、设计、文案、财务和法律等协作网络。','地区：上海市 / 上海市 / 浦东新区\n案例类型：文化创意\n是否为大学生创新创业：否\n发布日期：2026-06-24','AI建模；3D打印；交互影像系统','成立不到一年获老凤祥“上海礼物”设计大赛优秀设计奖；服务浦东美术馆、泗泾古镇等机构；已获得两项软件著作权','文化创意,AI建模,3D打印,交互影像系统','http://www.shobserver.com/sgh/detail?id=4010135',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(28,'一个人、一台电脑，“95后”OPC创业者勇闯“千万赛道”',44,'电商营销','卢冠男（Just AI）',66,'“95后”创业者卢冠男是Just AI创始人。他离开互联网大厂后，围绕中小商家的网络推广需求，用AI智能体“小加同学”根据产品图片和描述快速生成推广图文。随着AI从对话走向执行，他将更多精力投入客户接触和可盈利产品开发。','地区：广东省 / 深圳市 / 南山区\n案例类型：电商营销\n是否为大学生创新创业：否\n发布日期：2026-05-28','AI智能体“小加同学”；AI快速生成推广营销内容；Just AI海外服务平台','产品用户规模突破350万；付费B端商家达到1万家；团队规模从一人拓展到多人','电商营销,AI智能体“小加同学”,AI快速生成推广营销内容,Just AI海外服务平台','https://static.nfnews.com/content/202605/28/c12473333.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(29,'济南｜济南启动城市级数智生态OPC社区，发布十项政策礼包',37,'文化创意','王安众（三体智链（山东）数字科技有限公司）',67,'王安众是三体智链（山东）数字科技有限公司创始人，依托自研核心技术打造santibox 3D全息盒子。产品可自创虚拟形象，并与B站、优酷等平台动漫IP合作，使用户与IP形象实时互动、对话并在虚拟空间社交。','地区：山东省 / 济南市 / 无明确区县\n案例类型：文化创意\n是否为大学生创新创业：否\n发布日期：2026-02-12','AI-3D全息盒子；santibox 3D全息盒子；自创虚拟形象；实时互动、对话','产品已完成全流程测试与打样；预计2026年8月上市；已斩获5000台订单；公司现有8名成员','文化创意,AI-3D全息盒子,santibox 3D全息盒子,自创虚拟形象,实时互动,对话','http://www.shandong.gov.cn/art/2026/2/12/art_97564_705094.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(30,'抢占AI创业新赛道！罗庄区探索OPC新模式 拓宽青年人才“逐梦路”',37,'动漫短剧','Storyloom（临沂九天科技有限公司运营）',68,'Storyloom由临沂九天科技有限公司运营，聚焦AI短剧工业化生产。项目借助罗庄区OPC园区算力和软硬件环境，自研多智能体协同调度系统，把短剧内容生产链条自动化，形成接近单人操作的生产方式。','地区：山东省 / 临沂市 / 罗庄区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-06-19','多智能体协同调度系统；内容生产链条自动化','相较传统10—20人团队、3—4个月周期、30万—65万元一部，接近单人操作周期约3—5天、单部成本约3000元；生产周期缩短90%以上；已交付20余部短剧；净利率保持在50%以上','动漫短剧,多智能体协同调度系统,内容生产链条自动化','http://www.cnr.cn/sd/zt/lylz/lylzgdxw/20260619/t20260619_527668913.shtml',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(31,'德州聚焦优化营商环境构建全生命周期数智服务体系',37,'软件开发','韩立彬（齐元智汇（德州）数据科技有限公司）',69,'齐元智汇（德州）数据科技有限公司负责人韩立彬在齐河县完成企业注册登记，成为德州市首家人工智能OPC。公司专注人工智能基础数据服务、技术研究及应用场景落地推广，依托AI智能体和AI数字员工，为汽车、教育等领域提供“AI+”一站式解决方案。','地区：山东省 / 德州市 / 齐河县\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-04-15','AI智能体；AI数字员工；AI+一站式解决方案','不到半天完成营业执照办理；成为德州市首家人工智能OPC','软件开发,AI智能体,AI数字员工,AI+一站式解决方案','http://www.sd.xinhuanet.com/20260415/068eb575610a42b082c763a1a619c347/c.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(32,'专攻AI赛道里的“小而美”，这家“一人公司”凭啥年入百万？丨一人公司迎风口③',51,'办公效率','刘强（四川中欣数通科技有限公司）',70,'刘强创办四川中欣数通科技有限公司，聚焦面向中小企业的智能呼叫系统。AI大模型爆发后，他与南京公司合作开发并接入AI大模型，用于智能呼叫产品训练和售后处理，使系统更精准地应对不同场景并自动生成工单。','地区：四川省 / 成都市 / 无明确区县\n案例类型：办公效率\n是否为大学生创新创业：否\n发布日期：2026-03-13','智能呼叫系统；AI大模型；自动生成工单','合作客户超500家；2025年营收近百万元，较创业之初翻4倍；以往一天解决的问题现在十来分钟处理；一天能多处理三四十位客户售后问题；产品解决问题能力可达人工客服90%以上','办公效率,智能呼叫系统,AI大模型,自动生成工单','https://sichuan.scol.com.cn/ggxw/202603/83221880.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(33,'OPC生态森林正在生长！这里何以让创意青年“一个人战斗”？',32,'有声内容','户鹏飞（此声文化）',52,'南艺博士生户鹏飞创办公司“此声文化”，在南艺·元和塘大学生文创园相关OPC生态中开展有声数字文创业务。原文明确其用AI技术生产合成语音有声产品，围绕音频内容生产形成创业项目，并以学生创业者身份参与AI与文化艺术融合实践。','地区：江苏省 / 苏州市 / 相城区\n案例类型：有声内容\n是否为大学生创新创业：是\n发布日期：2026-01-26','AI技术生产合成语音有声产品','获得中国青年创青春大赛（2025）全国金奖；累计产出有声内容10万分钟','有声内容,大学生创新创业,AI技术生产合成语音有声产品','http://www.js.xinhuanet.com/20260126/293109e5e55d45bfa14c37522c23ba94/c.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(34,'上城鸿鹄汇重新定义AI时代创业新范式',33,'文化创意','王心怡（MetaLoft）',56,'王心怡是鸿鹄汇最年轻的入驻者，2001年出生，原文明确其为北京师范大学研三学生。她开发“MetaLoft”数字记忆景观互动应用，让用户上传照片后在虚拟城市中建造3D记忆空间，并通过AI为每个城市生成独特的数字风貌。','地区：浙江省 / 杭州市 / 上城区\n案例类型：文化创意\n是否为大学生创新创业：是\n发布日期：2025-12-18','AI为每个城市生成独特的数字风貌；3D记忆空间',NULL,'文化创意,大学生创新创业,AI为每个城市生成独特的数字风貌,3D记忆空间','https://www.hangzhou.gov.cn/col/col812264/art/2025/art_790ac3062e7c411abd17db2f7bacabb6.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(35,'上城区全省率先发布“一人公司”专项政策',33,'软件开发','冉伟（同路人）',59,'OPC创业者冉伟借助AI开发服务于OPC的创业生态平台“同路人”，并训练专属OPC的智能体“小路”。原文只说明其围绕OPC创业服务平台和智能体开展开发工作，因此本条仅记录其平台开发和智能体训练，不扩写用户规模、商业模式或收入。','地区：浙江省 / 杭州市 / 上城区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-03-04','AI；智能体“小路”','仅用48小时开发出服务于OPC的创业生态平台“同路人”','软件开发,AI,智能体“小路”','https://www.hzsc.com.cn/content/content_9881063.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(36,'一人如何成军？走进中关村“一人公司”',11,'软件开发','朱阳阳（录墨日记）',60,'朱阳阳曾在科技公司担任产品经理，2026年4月在中关村AI北纬社区注册公司。他的产品“录墨日记”通过输入碎片化文字、图片等信息，由AI生成可视化日记，帮助用户回溯生活经历；他也提到AI可辅助编写代码，让一人完成早期验证。','地区：北京市 / 北京市 / 海淀区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-05-07','AI辅助编写代码；由AI生成可视化日记',NULL,'软件开发,AI辅助编写代码,由AI生成可视化日记','http://kw.beijing.gov.cn/ztzl/rdzt/kjrmt/202605/t20260507_4639782.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(37,'一人如何成军？走进中关村“一人公司”',11,'音乐科技','王钰博',60,'王钰博是中关村AI北纬社区中的OPC创业者，原文称其拥有5年AI工程师经验、兼具20余年民乐功底。他利用视觉大模型搭建五线谱转简谱的智能转译系统，将AI能力应用到音乐记谱转译场景。','地区：北京市 / 北京市 / 海淀区\n案例类型：音乐科技\n是否为大学生创新创业：否\n发布日期：2026-05-07','视觉大模型；五线谱转简谱的智能转译系统','准确率超过95%','音乐科技,视觉大模型,五线谱转简谱的智能转译系统','http://kw.beijing.gov.cn/ztzl/rdzt/kjrmt/202605/t20260507_4639782.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(38,'一人如何成军？走进中关村“一人公司”',11,'软件开发','国纪龙',60,'国纪龙是复旦大学与北京中关村学院联合培养的在读博士，原文明确其开发聚焦人机协作的AI资源对接平台。在中关村AI北纬社区协助下，他完成公司注册，参与加速营与创业大赛，推动项目走向市场。','地区：北京市 / 北京市 / 海淀区\n案例类型：软件开发\n是否为大学生创新创业：是\n发布日期：2026-05-07','聚焦人机协作的AI资源对接平台',NULL,'软件开发,大学生创新创业,聚焦人机协作的AI资源对接平台','http://kw.beijing.gov.cn/ztzl/rdzt/kjrmt/202605/t20260507_4639782.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(39,'在成都怎么开一人公司？在听了36位创业者的分享后，得到的答案是……',51,'文化创意','史炳诚（灵龟工作室）',71,'灵龟工作室创始人史炳诚在天府软件π立方OPC社区评审会上展示自研游戏项目《赛博西游》。该项目用赛博朋克的叙事方式重新解构《西游记》经典故事，此前主要在家闭门开发，入驻诉求是寻找发行、投资和AI技术交流资源。','地区：四川省 / 成都市 / 高新区\n案例类型：文化创意\n是否为大学生创新创业：否\n发布日期：2026-03-12','AI工具','游戏开发已完成90%','文化创意,AI工具','http://scnews.newssc.org/system/20260312/001596962.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(40,'在成都怎么开一人公司？在听了36位创业者的分享后，得到的答案是……',51,'动漫短剧','曾秋云天（衔木映画漫剧工作室）',71,'成都信息工程大学大四学生曾秋云天和几位同学瞄准AI漫剧风口，成立衔木映画漫剧工作室。春节后，团队关注到AI视频生成大模型迭代升级，希望依托社区解决算力补充、资源整合、人才对接和财务处理等事务，专注打磨内容。','地区：四川省 / 成都市 / 高新区\n案例类型：动漫短剧\n是否为大学生创新创业：是\n发布日期：2026-03-12','AI视频生成大模型',NULL,'动漫短剧,大学生创新创业,AI视频生成大模型','http://scnews.newssc.org/system/20260312/001596962.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(41,'在成都怎么开一人公司？在听了36位创业者的分享后，得到的答案是……',51,'动漫短剧','袁欣（成都三刻奇想动漫科技有限公司）',71,'成都三刻奇想动漫科技有限公司创始人袁欣带领4人团队，用AI科技驱动漫剧创作。其团队研发“剧灵绘”AI多Agent全流程创作平台，覆盖灵感输入、剧本生成、角色建模、分镜绘制、视频合成和音频制作等流程。她将原本用于交租的资金投入技术研发和高质量数据采购。','地区：四川省 / 成都市 / 高新区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-03-12','“剧灵绘”AI多Agent全流程创作平台；火山引擎、可灵等头部大模型','产品迭代速度比在传统园区快了3倍以上','动漫短剧,“剧灵绘”AI多Agent全流程创作平台,火山引擎,可灵等头部大模型','http://scnews.newssc.org/system/20260312/001596962.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(42,'发放100万元信用贷款！成都首笔OPC贷款助力“单人成军”',51,'动漫短剧','王巍（四川元启共生人工智能科技有限公司）',72,'四川元启共生人工智能科技有限公司创始人王巍从承接AI漫剧制作起步，搭建OPC社区平台，提供算力、场地，并通过自建商务部门为技术型OPC对接业务，以“找到业务再分钱”的模式形成创业共同体。团队还孵化学员并吸引多家OPC创业团队入驻，帮助创业者承接业务。','地区：四川省 / 成都市\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-04-15','AIGC；AI智能体应用','获得成都银行100万元信用贷款；一年内发展为近百人团队、拥有3000平米社区','动漫短剧,AIGC,AI智能体应用','http://sc.people.com.cn/n2/2026/0415/c379469-41553000.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(43,'皖北首个OPC创业社区落户市科创中心 “一人+AI”解锁创业新可能',34,'电商营销','麦腾创谷OPC创业团队',73,'麦腾创谷OPC创业团队联合开发OPC技术项目，为跨境POD行业完成全链条技术、市场、后端及供应链开发，形成“个人开店、全链赋能”的轻量创业模式。本地化推广后，可带动算力、数据、物流、生产厂家等上下游订单招商。','地区：安徽省 / 淮北市\n案例类型：电商营销\n是否为大学生创新创业：否\n发布日期：2026-03-05',NULL,'已拥有2000多个用户','电商营销','https://www.huaibei.gov.cn/zwgk/public/15/64938099.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(44,'山东多地布局OPC社区 培育智能经济新生态',37,'动漫短剧','石磊',74,'“90后”创业者石磊在日照大学城OPC创业社区调动多个AI智能体协同作业，一人完成短剧从创意到成片的全流程。入驻社区前，他主要承接其他工作室剩余订单；入驻后获得社区对接的一手订单。他表示此前承接二手订单单价低且不稳定，入驻后可对接社区资源。','地区：山东省 / 日照市\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-06-12','多个AI智能体协同作业','社区给对接了两个“一手订单”','动漫短剧,多个AI智能体协同作业','http://news.qq.com/rain/a/20260612A09EUJ00',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(45,'一个人就是一家公司？市中区首个OPC企业落地山东未来云谷',37,'软件开发','康建峰（济南泉峰信息技术有限公司）',75,'济南泉峰信息技术有限公司负责人康建峰将企业落地山东未来云谷，借助科大讯飞等园区企业的技术优势和数智生态OPC社区服务，低成本调用AI能力，降低技术门槛，推动AI技术在垂直领域落地。其团队关注不同模型适配不同业务，推动AI在细分场景下应用。','地区：山东省 / 济南市 / 市中区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-03-21','讯飞线上开放平台；成熟智能体资源；AI“虚拟员工”',NULL,'软件开发,讯飞线上开放平台,成熟智能体资源,AI“虚拟员工”','http://www.jinan.gov.cn/zt/2025nzt/yhyshj/qxdt/art/2026/art_57fe709500b840372ed292788a0acb4e.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(46,'山东多地布局OPC社区 培育智能经济新生态',37,'软件开发','高金豹（聊城市跃豹智能科技有限公司）',74,'聊城市跃豹智能科技有限公司负责人高金豹通过东昌府区OPC专属服务体系办理经营范围变更，以合规承接更多智能体研发、AI技术应用订单，灵活对接市场需求。报道重点呈现其通过政务服务完善经营资质。此次变更经营范围是为了合规拓展智能科技业务。','地区：山东省 / 聊城市 / 东昌府区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-06-12','智能体研发、AI技术应用',NULL,'软件开发,智能体研发,AI技术应用','http://news.qq.com/rain/a/20260612A09EUJ00',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(47,'“一人公司”的集体生活',42,'电商营销','翁多嘉（轻尾科技）',76,'翁多嘉和丈夫魏煜朋共同支撑轻尾科技，入驻武昌滨江亲橙人工智能OPC社区后，在相邻工位开展商务清单梳理和新媒体账号引流工作。她通过社区培训和资源链接结识合作伙伴，并利用稳定工位提升办公效率。她表示社区以较低成本提供稳定工位，并链接同行和本地资源。','地区：湖北省 / 武汉市 / 武昌区\n案例类型：电商营销\n是否为大学生创新创业：否\n发布日期：2026-05-22','AI','社区内像轻尾科技这样“小而美”的创业主体超百家','电商营销,AI','http://hb.people.com.cn/n2/2026/0522/c194063-41587892.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(48,'“一人公司”的集体生活',42,'软件开发','魏煜朋（轻尾科技）',76,'魏煜朋与翁多嘉共同运营轻尾科技，入驻亲橙人工智能OPC社区后，丈夫负责代码开发，妻子负责商务和引流。报道呈现该夫妻团队以轻量组织方式开展创业，在社区工位中协同推进业务。二人以前居家办公缺少氛围，入驻后围绕代码开发、商务和引流分工协作。','地区：湖北省 / 武汉市 / 武昌区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-05-22','AI','社区内像轻尾科技这样“小而美”的创业主体超百家','软件开发,AI','http://hb.people.com.cn/n2/2026/0522/c194063-41587892.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(49,'“一人公司”的集体生活',42,'动漫短剧','黄梓皓',76,'黄梓皓曾是程序员，看到相关软件足够成熟、能实现创作诉求后辞职创业。他看中AI漫剧市场前景，带领3人团队入驻亲橙人工智能OPC社区，依托AI生成与剪辑工具完成短剧制作。他认为一人公司崛起源于AI改变生产方式，现场正调试AI生成的视频画面。','地区：湖北省 / 武汉市 / 武昌区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-05-22','AI生成与剪辑工具','仅用20天就能完成一部短剧；首个AI漫剧视频已上线，播放量达到预期','动漫短剧,AI生成与剪辑工具','http://hb.people.com.cn/n2/2026/0522/c194063-41587892.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(50,'“一人公司”的集体生活',42,'软件开发','陈磊',76,'陈磊是亲橙人工智能OPC社区较早入驻的创业者，日常在社区打磨智慧诊疗平台。他借助AI节省程序员成本，将精力集中在核心攻关，并在社区结识医疗推广创业团队，合作拓展业务。他表示运营仍需自己负责，并通过社区合作把平台推向业务拓展。','地区：湖北省 / 武汉市 / 武昌区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-05-22','AI','与医疗推广创业团队签约合作拓展业务','软件开发,AI','http://hb.people.com.cn/n2/2026/0522/c194063-41587892.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(51,'“每周都有新团队入驻” 经开智造人工智能OPC社区聚集超60家“超级个体”',42,'教育培训','肖筱（武汉市艺起科技有限公司）',77,'“95后”肖筱从英国埃克塞特大学人工智能专业毕业后，与江晓渔联合创立武汉市艺起科技有限公司。团队通过AI对话为学生进行能力画像，分层筛选有潜力的创新者，并组织内容创作比赛，让作品集对接企业项目或入职机会。','地区：湖北省 / 武汉市 / 武汉经开区\n案例类型：教育培训\n是否为大学生创新创业：否\n发布日期：2026-06-25','TalentFlow AI；AI对话；AI短视频、AI漫剧、创意广告；AI编程','TalentFlow AI项目已落地','教育培训,TalentFlow AI,AI对话,AI短视频,AI漫剧,创意广告,AI编程','https://tctest.wuhan.gov.cn/tzwh/tzzx/202606/t20260625_2781278.shtml',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(52,'“每周都有新团队入驻” 经开智造人工智能OPC社区聚集超60家“超级个体”',42,'教育培训','江晓渔（武汉市艺起科技有限公司）',77,'华中科技大学计算机专业硕士研究生江晓渔与肖筱联合创立武汉市艺起科技有限公司。团队用AI对话为学生做能力画像，筛选创新者并组织内容创作比赛，使学生凭优秀作品集对接企业项目或就业机会。团队还计划把服务范围延伸至AI编程等更深层次技术领域。','地区：湖北省 / 武汉市 / 武汉经开区\n案例类型：教育培训\n是否为大学生创新创业：是\n发布日期：2026-06-25','TalentFlow AI；AI对话；AI短视频、AI漫剧、创意广告；AI编程','TalentFlow AI项目已落地','教育培训,大学生创新创业,TalentFlow AI,AI对话,AI短视频,AI漫剧,创意广告,AI编程','https://tctest.wuhan.gov.cn/tzwh/tzzx/202606/t20260625_2781278.shtml',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(53,'“每周都有新团队入驻” 经开智造人工智能OPC社区聚集超60家“超级个体”',42,'教育培训','柳勇（湖北知行湖畔教育科技有限公司）',77,'“00后”柳勇去年从江汉大学硕士研究生毕业后，联合校友创立湖北知行湖畔教育科技有限公司。公司以人工智能技术为核心，聚焦教育咨询、招生辅助、业务培训、会议及展览，打造一站式AI教育服务生态。团队正在推进AI智能体产品，为高中生做专业分析并提供个性化志愿填报服务。','地区：湖北省 / 武汉市 / 武汉经开区\n案例类型：教育培训\n是否为大学生创新创业：是\n发布日期：2026-06-25','人工智能技术；AI智能体产品',NULL,'教育培训,大学生创新创业,人工智能技术,AI智能体产品','https://tctest.wuhan.gov.cn/tzwh/tzzx/202606/t20260625_2781278.shtml',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(54,'“每周都有新团队入驻” 经开智造人工智能OPC社区聚集超60家“超级个体”',42,'软件开发','代齐祥',77,'江汉大学计算机专业大四学生代齐祥通过经开智造人工智能OPC社区承接平台任务。社区合作方CSDN派发小任务并根据交付速度和质量给团队评级，评级越高后续可获得更大订单。他在社区专项派发订单中受益，后续可依评级获取更大订单。','地区：湖北省 / 武汉市 / 武汉经开区\n案例类型：软件开发\n是否为大学生创新创业：是\n发布日期：2026-06-25','model grid平台；token券；20万词元免费算力','过去半个多月接了三个任务，累计收入超过3000元','软件开发,大学生创新创业,model grid平台,token券,20万词元免费算力','https://tctest.wuhan.gov.cn/tzwh/tzzx/202606/t20260625_2781278.shtml',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(55,'“一人公司”不再孤勇 长沙天心数谷开启大学生创业新生态',43,'教育培训','李泽（湖南智泽云科技发展有限公司）',78,'湖南智泽云科技发展有限公司负责人李泽带领4人团队，专注为高校提供云实验室整体解决方案。入驻天心数谷创业孵化基地后，团队享受办公场地3年免租、工商注册代办等服务，降低了初创运营成本。入驻后团队把场地和注册压力转化为产品交付与客户服务精力。','地区：湖南省 / 长沙市 / 天心区\n案例类型：教育培训\n是否为大学生创新创业：否\n发布日期：2026-04-10',NULL,'2026年第一季度营收20多万元','教育培训','http://hn.people.com.cn/n2/2026/0410/c336521-41548303.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(56,'“一人公司”不再孤勇 长沙天心数谷开启大学生创业新生态',43,'软件开发','鲁威龙',78,'鲁威龙聚焦汽车自动驾驶数据标注，选择入驻天心数谷创业孵化基地。他看重基地的产业优势、政策支持，以及通过湖南大数据交易所接单的机会，以数据标注业务作为创业方向。他表示这一接单渠道对初创团队很重要，能帮助项目获得早期业务来源。','地区：湖南省 / 长沙市 / 天心区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-04-10','数据标注；人工智能',NULL,'软件开发,数据标注,人工智能','http://hn.people.com.cn/n2/2026/0410/c336521-41548303.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(57,'“一人公司”不再孤勇 长沙天心数谷开启大学生创业新生态',43,'助农振兴','徐佩（湖南新发农业科技有限公司）',78,'湖南新发农业科技有限公司负责人徐佩是一名在读研究生，选择天心数谷创业孵化基地，看重天心区的资源共享及政策扶持。她利用数智AI技术为传统黄花菜产业赋能，尝试将“土特产”变成“科技疗愈品”。其项目把农业产品与科技疗愈场景结合，围绕传统产业寻找新应用。','地区：湖南省 / 长沙市 / 天心区\n案例类型：助农振兴\n是否为大学生创新创业：是\n发布日期：2026-04-10','数智AI技术',NULL,'助农振兴,大学生创新创业,数智AI技术','http://hn.people.com.cn/n2/2026/0410/c336521-41548303.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(58,'湖南首个OPC创业中心落户长沙望城 打造全链条生态赋能创新创业',43,'软件开发','李金（长沙科聚智研科技有限公司）',79,'长沙科聚智研科技有限公司负责人李金介绍，企业专注于智能机器人研发、生产、制造与销售，在望城创智岛产业园拥有近400平方米基地和厂房。望城提供场地、租金减免、工商注册和项目发展规划等服务，支持其投入研发和生产。','地区：湖南省 / 长沙市 / 望城区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-03-18','人工智能技术',NULL,'软件开发,人工智能技术','https://local.cctv.com/2026/03/18/ARTI9fjFITHARmf9kv716Zh9260318.shtml',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(59,'“一人公司”兴起，福建加速布局AI赋能个体创业新赛道',35,'办公效率','孙智聪（福州堆栈科技有限公司）',80,'福州堆栈科技有限公司负责人孙智聪带队从基础设施结构健康监测业务延伸到智能体研发，推出面向复杂任务处理的“龙虾智能体”和面向个人用户及中小企业的“秋田智能体”，通过多智能体协同架构拆分并整合任务流程。系统可按任务需求让不同智能体完成信息检索、数据分析和内容生成。','地区：福建省 / 福州市 / 仓山区\n案例类型：办公效率\n是否为大学生创新创业：否\n发布日期：2026-07-01','“龙虾智能体”(OpenClaw)；“秋田智能体”(OpenAkita)；多智能体协同架构','相关产品已应用于跨境电商、自媒体运营、企业办公等场景','办公效率,“龙虾智能体”(OpenClaw),“秋田智能体”(OpenAkita),多智能体协同架构','https://www.fj.chinanews.com.cn/news/2026/2026-07-01/586913.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(60,'漳州创建全省首家AI+OPC促进发展中心',35,'电商营销','彭坚毅（漳州龙文路鑫隆网络科技有限公司）',81,'大专毕业刚一年的“00后”彭坚毅负责漳州龙文路鑫隆网络科技有限公司，夜间运营跨境电商OPC。他的女装裙子赛道由AI工具串联选品、图文生成、文案、海外社媒营销、客服和数据分析，并在陪跑机构帮助下培养运营思维。','地区：福建省 / 漳州市 / 龙文区\n案例类型：电商营销\n是否为大学生创新创业：否\n发布日期：2026-05-25','白驹翼；即梦AI；豆包；ChatGPT；AI英文自动回复；Grammarly；平台工具','月均稳定收入数千元','电商营销,白驹翼,即梦AI,豆包,ChatGPT,AI英文自动回复,Grammarly,平台工具','http://fjnews.fjsen.com/wap/2026-05/25/content_32190398.htm',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(61,'“一人公司”如何成为“超级个体”？',35,'电商营销','刘世奇（泉州市蒂万坦斯贸易有限公司）',82,'刘世奇在晋江创办泉州市蒂万坦斯贸易有限公司，从跨境电商选品切入，将AI介入全球平台数据分析、商品上架、营销素材创作、广告投流和客户接待等环节，推出“丑拖鞋”等产品，并把团队成员定义为各业务板块的OPC决策者。','地区：福建省 / 泉州市 / 晋江市\n案例类型：电商营销\n是否为大学生创新创业：否\n发布日期：2026-02-02','ChatGPT3.5；AI能够抓取全球跨境平台的海量数据；商品上架、营销素材创作、广告投流、客户接待','订单转化率从9.96%上升至21.67%，投产比增长2.4倍；2024年营收突破3000万元，人均效能可达500万元','电商营销,ChatGPT3.5,AI能够抓取全球跨境平台的海量数据,商品上架,营销素材创作,广告投流,客户接待','https://www.fujian.gov.cn/zwgk/ztzl/sxzygwzxsgzx/sdjj/szjj/202602/t20260202_7087824.htm',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(62,'“一人公司”如何成为“超级个体”？',35,'软件开发','林福川（东际网丰（福建）科技有限公司）',82,'东际网丰（福建）科技有限公司创始人林福川长期从事软件研发，创业后打造数字化智能监测平台，通过前端感知设备构建多维度识别预警模型，捕捉运行隐患并自动生成深度分析报告，实现实时推送与分级预警。他曾在项目一线摸排痛点，反复迭代数十个版本以贴合行业需求。','地区：福建省\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-02-02','AI化身为强大的“知识翻译官”与“逻辑加速器”','反复迭代数十个版本','软件开发','https://www.fujian.gov.cn/zwgk/ztzl/sxzygwzxsgzx/sdjj/szjj/202602/t20260202_7087824.htm',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(63,'“一人公司”如何成为“超级个体”？',35,'电商营销','听海',82,'前互联网大厂产品经理“听海”切入图书种草变现赛道，用AI工具拆解爆款规律，搭建标准化内容生产流程。报道呈现其以OPC模式降低成本、提高时间自由度，并将内容生产与商业变现结合。报道称该路径让她获得更低成本、更自由时间和更可控的成长空间。','地区：福建省\n案例类型：电商营销\n是否为大学生创新创业：否\n发布日期：2026-02-02','AI工具拆解爆款规律','4个月积累超过35万粉丝，营收突破30万元','电商营销,AI工具拆解爆款规律','https://www.fujian.gov.cn/zwgk/ztzl/sxzygwzxsgzx/sdjj/szjj/202602/t20260202_7087824.htm',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(64,'“一人公司”如何成为“超级个体”？',35,'教育培训','戴越',82,'内容创作者戴越将小学语文课文制作成视觉化AI微电影，用AIGC快速产出高质量教学内容。报道将其作为福建青年以OPC模式进行专业化内容生产的案例，强调其借助AI重构工作方式。报道将其作为用AI重构工作方式、探索专业化内容生产方案的案例。','地区：福建省\n案例类型：教育培训\n是否为大学生创新创业：否\n发布日期：2026-02-02','AIGC快速产出高质量的教学内容','作品《大青树下的小学》获2025年中国创新影像大赛一等奖','教育培训,AIGC快速产出高质量的教学内容','https://www.fujian.gov.cn/zwgk/ztzl/sxzygwzxsgzx/sdjj/szjj/202602/t20260202_7087824.htm',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(65,'从一家工作室看重庆“一人公司”崛起',50,'动漫短剧','王禹（重庆Edge404工作室）',83,'王禹与陈伟于2026年初创立重庆Edge404工作室，瞄准AI短剧与智能体开发。王禹介绍团队在不到10平方米的书房办公，并依托Claude GPT系列AI模型开发饮品推介智能体，还为向日葵运动科技开发智能化运营平台。','地区：重庆市 / 重庆市 / 两江新区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-04-03','Claude GPT系列AI模型；Openclaw智能体底座','向DramaBox交付47秒AI“精品真人剧”样片；2小时完成饮品推介智能体；一周开发智能化运营平台','动漫短剧,Claude GPT系列AI模型,Openclaw智能体底座','http://www.cq.xinhuanet.com/20260403/49f8f71c3552499fa4842cef71a5e004/c.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(66,'从一家工作室看重庆“一人公司”崛起',50,'动漫短剧','陈伟（重庆Edge404工作室）',83,'陈伟2025年从纽约电影学院硕士毕业后归国扎根重庆，与王禹共同创立重庆Edge404工作室，聚焦AI短剧与智能体开发。团队把AI用于短剧样片、点单小程序智能体和企业智能化运营平台开发。他把影视专业经验与AI短剧制作结合，推动工作室向海外平台提交样片。','地区：重庆市 / 重庆市 / 两江新区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-04-03','Claude GPT系列AI模型；Openclaw智能体底座','向DramaBox交付47秒AI“精品真人剧”样片；2小时完成饮品推介智能体；一周开发智能化运营平台','动漫短剧,Claude GPT系列AI模型,Openclaw智能体底座','http://www.cq.xinhuanet.com/20260403/49f8f71c3552499fa4842cef71a5e004/c.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(67,'全市首个“AI + 应用”OPC社区迎来首批企业入驻',50,'软件开发','比特星河',84,'比特星河是两江新区星运人工智能OPC社区首批签约入驻企业之一，聚焦AI Agent研发赋能垂直领域落地，在法律、生活娱乐等垂直领域打造应用。企业入驻诉求包括算力补贴、金融信贷、场景支持和制造企业场景资源。','地区：重庆市 / 重庆市 / 两江新区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-03-27','AI Agent','在法律、生活娱乐等垂直领域打造了多款应用','软件开发,AI Agent','https://www.liangjiang.gov.cn/mixmedia/a/202603/27/WS69c6553fe4b0adfdc817bfbe.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(68,'全市首个“AI + 应用”OPC社区迎来首批企业入驻',50,'办公效率','界合智能',84,'界合智能旨在帮助中小企业将AI更好融入业务流程。入驻两江新区星运人工智能OPC社区后，企业看重算力、办公地政策以及两江产运公司对接的企业需求清单，以便开展业务。入驻后通过社区对接企业需求清单，推动AI能力与中小企业流程结合。','地区：重庆市 / 重庆市 / 两江新区\n案例类型：办公效率\n是否为大学生创新创业：否\n发布日期：2026-03-27','AI',NULL,'办公效率,AI','https://www.liangjiang.gov.cn/mixmedia/a/202603/27/WS69c6553fe4b0adfdc817bfbe.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(69,'AI赋能“超级个体”，仙桃数据谷打造OPC创业新高地',50,'办公效率','冷奇峰（争取科技）',85,'争取科技创始人冷奇峰在仙桃数据谷“未来星·OPC能力提升营”创业分享环节，以“数据为底，AI为眼”为题，展示数据资产如何借助AI释放商业价值，为创业者提供AI时代数据应用的案例参考。他的分享面向软件从业者和创业者，围绕数据资产商业价值转化展开。','地区：重庆市 / 重庆市 / 两江新区\n案例类型：办公效率\n是否为大学生创新创业：否\n发布日期：2026-06-17','AI',NULL,'办公效率,AI','https://www.liangjiang.gov.cn/mixmedia/a/202606/17/WS6a320927e4b0adfdc8183229.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(70,'AI赋能“超级个体”，仙桃数据谷打造OPC创业新高地',50,'办公效率','刘秋实（腾势达新能源科技公司）',85,'腾势达新能源科技公司CEO刘秋实在仙桃数据谷活动中分享新能源配套与AI管理体系“双剑合璧”的转型实践。报道将其作为传统企业数字化转型的案例，呈现AI管理体系与新能源配套业务结合的路径。该实践被报道作为传统企业数字化转型可复制的经验样本。','地区：重庆市 / 重庆市 / 两江新区\n案例类型：办公效率\n是否为大学生创新创业：否\n发布日期：2026-06-17','AI管理体系',NULL,'办公效率,AI管理体系','https://www.liangjiang.gov.cn/mixmedia/a/202606/17/WS6a320927e4b0adfdc8183229.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(71,'两江新区仙桃数据谷打造“一人公司”社区',50,'软件开发','智佰邦科技',86,'智佰邦科技是仙桃数据谷“AI+大模型训练”社区中的5人小团队，专注承接菲利信的数据标注业务。报道将其作为园区精准分池培育的案例，体现小团队在OPC社区中承接链主企业任务。园区将该团队纳入“AI＋大模型训练”社区，承接链主企业拆分的标注任务。','地区：重庆市 / 重庆市 / 两江新区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-03-19','AI＋大模型训练；数据标注','去年营收做到250万元','软件开发,AI＋大模型训练,数据标注','https://www.liangjiang.gov.cn/mixmedia/a/202603/19/WS69bbb89fe4b0adfdc817b4e2.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(72,'在这里，“一人公司”抱团生长',12,'文化创意','徐帅',87,'香薰文创创业者徐帅入驻天美86H艺术园区前，手握文创设计图纸却缺少客源渠道和对接资源，只能背着样品走访商家。加入X-OPC后，园区帮助其链接销售渠道，并联动天美艺术街区线下文创门店代售自主研发香薰，还对接本地自行车品牌香卡配饰合作。','地区：天津市 / 天津市 / 河北区\n案例类型：文化创意\n是否为大学生创新创业：否\n发布日期：2026-06-22',NULL,'入驻园区几个月，产品销售额比初期翻了两倍多','文化创意','http://epaper.tianjinwe.com/tjrb/h5/html5/2026-06/22/content_143080_3561457.htm',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(73,'在这里，“一人公司”抱团生长',12,'动漫短剧','李永俊',87,'来自北京的AI漫剧制作人李永俊考察多地创业环境后，选择落户天美86H艺术园区。他看重园区提供的专属算力支持，以此节省运营开支，也借助园区搭建的产学研通道，在业务高峰期对接天津美院动漫专业学生参与制作。','地区：天津市 / 天津市 / 河北区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-06-22','AI漫剧；专属算力支持',NULL,'动漫短剧,AI漫剧,专属算力支持','http://epaper.tianjinwe.com/tjrb/h5/html5/2026-06/22/content_143080_3561457.htm',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(74,'西部首个AI-OPC创新社区落地西安高新区 激活“一人公司”创业新动能',61,'办公效率','张雷',88,'张雷2025年6月从浙江一家互联网大厂离职后回到西安创办一人公司。他自主研发“百灵”软件，让用户对话的对象从好友变为“数字员工”，由AI智能体协助完成文案撰写、财务整理、数据分析、市场调研等工作，并在社区降低办公场地租金和算力成本后继续轻资产运营。','地区：陕西省 / 西安市 / 高新区\n案例类型：办公效率\n是否为大学生创新创业：否\n发布日期：2026-05-13','“百灵”软件；数字员工；AI智能体',NULL,'办公效率,“百灵”软件,数字员工,AI智能体','https://shx.chinadaily.com.cn/a/202605/13/WS6a03ed17a310942cc49abfa6.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(75,'西安人工智能OPC创新社区如何赋能AI超级个体？',61,'教育培训','杨晶（陕西晶淼企业管理咨询有限公司）',89,'陕西晶淼企业管理咨询有限公司创始人杨晶捕捉到OPC趋势后，于2026年1月带队搭建“西安首个OPC超级个体社群”，围绕OPC创业者开展政策宣讲、职业生涯和就业培训，并组织智能体开发与AIGC应用课程。','地区：陕西省 / 西安市 / 高新区\n案例类型：教育培训\n是否为大学生创新创业：否\n发布日期：2026-03-30','扣子；智能体开发与AIGC应用；AI工具','2026年1月搭建“西安首个OPC超级个体社群”','教育培训,扣子,智能体开发与AIGC应用,AI工具','http://dianzibao.cb.com.cn/images/2026-03/30/11/2645B07B.pdf',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(76,'单人成军，河南“AI+超级个体”新生态咋养成？',41,'办公效率','张玉魁',90,'河南中医药大学学生、05后AI企业落地开发者张玉魁在OpenClaw应用场景拆解与落地分享会上，以实操形式展示AI在企业落地的场景，包括作为数据员工进行数据分析、作为个人创作助手进行公众号文章创作、搭建小红书流量矩阵管理系统等。','地区：河南省 / 郑州市 / 中原科技城\n案例类型：办公效率\n是否为大学生创新创业：是\n发布日期：2026-03-19','OpenClaw；数据员工；个人创作助手；小红书流量矩阵管理系统','现场展示数据助手在5分钟内完成过去需要3天时间才能完成的报表任务','办公效率,大学生创新创业,OpenClaw,数据员工,个人创作助手,小红书流量矩阵管理系统','https://www.hnjjbs.com/article/2026-03/177391093349870.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(77,'从“拎包入驻”到“拎脑入驻” 一人公司成“创业郑州”新风尚',41,'动漫短剧','赵武佳（河南知行影视科技有限公司）',91,'赵武佳曾深耕线下微短剧，几个月前转型成为河南知行影视科技有限公司创始人，全身心投入AI真人短剧制作领域。其业务从传统微短剧拍摄转向借助AI技术完成短剧制作，切入网络微短剧这一AI技术落地应用赛道，并将微短剧作为数字内容产业方向推进。','地区：河南省 / 郑州市 / 高新区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-04-19','AI技术；AI真人短剧制作','传统80集微短剧需四五十人两个多月完成；如今七八个人一周可完成同等规格短剧制作','动漫短剧,AI技术,AI真人短剧制作','https://m.henan.gov.cn/2026/04-19/3343797.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(78,'深耕校企协同创新 赋能AI新消费东盟出海',45,'电商营销','莫震宇（广西境跃智能科技有限公司）',92,'广西外国语学院2024届数字科技学院毕业生莫震宇代表初创企业广西境跃智能科技有限公司，在广西AI+新消费出海OPC社区开放运营仪式上发布新产品《POC AI跨境客服销售协同体》，并代表企业领取首批OPC企业入驻证书。','地区：广西壮族自治区 / 南宁市 / 青秀区\n案例类型：电商营销\n是否为大学生创新创业：否\n发布日期：2026-06-30','《POC AI跨境客服销售协同体》；AI智能跨境客服销售协同体','获得首批OPC企业入驻证书','电商营销,《POC AI跨境客服销售协同体》,AI智能跨境客服销售协同体','https://sei.gxufl.edu.cn/info/111548',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(79,'深耕校企协同创新 赋能AI新消费东盟出海',45,'文化创意','李浩霖（广西翼斧云天智能科技有限公司）',92,'广西外国语学院国际传媒学院2025级在校生李浩霖代表广西翼斧云天智能科技有限公司领取青秀创新中心首批OPC企业入驻证书。其团队来自2024级会计学院的石晶晶在新技术、新产品发布环节分享《F3P航模创新引领成果》。','地区：广西壮族自治区 / 南宁市 / 青秀区\n案例类型：文化创意\n是否为大学生创新创业：是\n发布日期：2026-06-30',NULL,'获得首批OPC企业入驻证书','文化创意,大学生创新创业','https://sei.gxufl.edu.cn/info/111548',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(80,'青蓝·创讲坛 | 抢抓AI创业政策风口 深耕本土特色内容赛道',36,'教育培训','周剑（中才智聘（江西）人才服务有限公司）',93,'中才智聘（江西）人才服务有限公司总经理、OPC青创中心负责人周剑在南昌工学院AI漫剧OPC超级个体创业专题讲座中，围绕AI漫剧行业、本土特色内容赛道、内容变现模式和创业合规流程，梳理青年创业落地体系，并与师生交流OPC注册和AI创作成本管控问题。','地区：江西省 / 南昌市 / 红谷滩新区\n案例类型：教育培训\n是否为大学生创新创业：否\n发布日期：2026-06-24','AI漫剧OPC；Token普惠；AI算力','讲座吸引全校400余名师生到场参与','教育培训,AI漫剧OPC,Token普惠,AI算力','https://cxcy.ncpu.edu.cn/xinwenzhongxin/zuixindongtai/html.php?c-4549.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(81,'沈阳首个“数据+AI+OPC”平台孵化30余家“一人公司”',21,'文化创意','喻中场',94,'喻中场是星元创智数据智能OPC孵化社区孵化两个月的OPC创业者，独立完成“二桃斗三士”游戏开发。该游戏取材于经典历史典故，打造“双地主”对阵“三农民”的国风5人扑克对战玩法，融合国风美学与传统文化；开发完成后，他计划依托社区支持申请游戏版号并推向网络平台。','地区：辽宁省 / 沈阳市 / 和平区\n案例类型：文化创意\n是否为大学生创新创业：否\n发布日期：2026-06-22','数据、算力、模型','开发完成后已有企业出价七位数洽谈购买','文化创意,数据,算力,模型','https://epaper.syd.com.cn/syrb/h5/html5/2026-06/22/content_121055_19637819.htm',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(82,'沈阳首个“数据+AI+OPC”平台孵化30余家“一人公司”',21,'软件开发','马喆',94,'马喆是星元创智数据智能OPC孵化社区孵化时长仅3个月的创业者，开发出面向企业与园区场景的建筑能耗分析模型。该项目聚焦企业和园区能耗分析场景，将数据智能能力用于能源管理类应用，在平台数据、算力、模型支撑下形成面向园区运营的分析产品。','地区：辽宁省 / 沈阳市 / 和平区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-06-22','建筑能耗分析模型；数据、算力、模型','孵化时长仅3个月','软件开发,建筑能耗分析模型,数据,算力,模型','https://epaper.syd.com.cn/syrb/h5/html5/2026-06/22/content_121055_19637819.htm',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(83,'沈阳首个“数据+AI+OPC”平台孵化30余家“一人公司”',21,'办公效率','宋嘉禾',94,'宋嘉禾在星元创智数据智能OPC孵化社区打造智慧园区能碳运营平台，直击传统人工效率低、数据零散等痛点。项目面向园区运营场景，通过数据智能方式提升园区能碳管理与运营效率，并在社区数据、算力和模型托举下形成能碳运营类产品。','地区：辽宁省 / 沈阳市 / 和平区\n案例类型：办公效率\n是否为大学生创新创业：否\n发布日期：2026-06-22','智慧园区能碳运营平台；数据、算力、模型',NULL,'办公效率,智慧园区能碳运营平台,数据,算力,模型','https://epaper.syd.com.cn/syrb/h5/html5/2026-06/22/content_121055_19637819.htm',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(84,'沈阳首个“数据+AI+OPC”平台孵化30余家“一人公司”',21,'办公效率','刘知微',94,'刘知微是星元创智数据智能OPC孵化社区孵化2个月的创业者，研发了政务热线工单智能分派系统。该系统面向政务服务工单分派场景，将数据智能能力用于热线工单分派和服务流程处理，报道称其提升政务服务精细化水平。','地区：辽宁省 / 沈阳市 / 和平区\n案例类型：办公效率\n是否为大学生创新创业：否\n发布日期：2026-06-22','政务热线工单智能分派系统；数据、算力、模型','孵化2个月','办公效率,政务热线工单智能分派系统,数据,算力,模型','https://epaper.syd.com.cn/syrb/h5/html5/2026-06/22/content_121055_19637819.htm',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(85,'沈阳首个“数据+AI+OPC”平台孵化30余家“一人公司”',21,'软件开发','林若楠',94,'林若楠在星元创智数据智能OPC孵化社区构建肠道菌群智能诊断平台，利用AI降低专业报告的解读门槛。该项目将AI能力用于医疗健康领域的报告理解与辅助诊断场景，并依托社区数据、算力和模型支撑推进智能诊断平台建设。','地区：辽宁省 / 沈阳市 / 和平区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-06-22','肠道菌群智能诊断平台；AI',NULL,'软件开发,肠道菌群智能诊断平台,AI','https://epaper.syd.com.cn/syrb/h5/html5/2026-06/22/content_121055_19637819.htm',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(86,'从一个创业社区样本看见OPC生长力',21,'电商营销','孙帅（沈阳茶马电子商务有限公司）',95,'沈阳茶马电子商务有限公司总经理孙帅较早尝到AI创业红利，获得聚沙OPC创业社区提供的资金支持，使茶马跨境电商项目驶上发展快车道。他还与聚焦空间（沈阳）科技服务有限公司合作，打造“龙头带领+OPC孵化”模式。','地区：辽宁省 / 沈阳市 / 大东区\n案例类型：电商营销\n是否为大学生创新创业：否\n发布日期：2026-06-16','AI技术赋能',NULL,'电商营销,AI技术赋能','https://epaper.syd.com.cn/syrb/html/2026-06/16/content_121051_19623955.htm',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(87,'力撑OPC：净月种下首批“超级个体”种子',22,'动漫短剧','孟繁威（长春市他山影视文化有限公司）',96,'97年出生的孟繁威原为房地产渠道分销从业者，看到吉林青年影视OPC创新中心首期招募后成为第一期学员。他围绕AI短剧和影视轻量化制作学习AI写剧本、生成图片、视频制作及后期剪辑，系统使用ChatGPT、Midjourney、剪映等工具，结业后注册长春市他山影视文化有限公司并入驻中心。','地区：吉林省 / 长春市 / 净月高新区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-06-02','AI写剧本；生成图片；视频制作；后期剪辑；ChatGPT；Midjourney；剪映',NULL,'动漫短剧,AI写剧本,生成图片,视频制作,后期剪辑,ChatGPT,Midjourney,剪映','http://ishare.ifeng.com/c/s/8tcl0Th10Fz?aman=9n678f370f9a3Mb4bmd0b',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(88,'力撑OPC：净月种下首批“超级个体”种子',22,'动漫短剧','杨桃（长春市星芒映画数字创意有限公司）',96,'曾是教师的杨桃看好AI前景，报名净月高新区影视局、团省委主办的吉林青年影视OPC创新中心培训。她完成第一期课程后注册长春市星芒映画数字创意有限公司，主攻AI短剧与短视频制作，并依托中心对接订单、统一派发代制订单，与其他首批学员抱团协作分摊成本、交流经验。','地区：吉林省 / 长春市 / 净月高新区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-06-02','AI短剧；短视频制作；AIGC影视全流程应用','杨桃估算现有订单足够两年生产','动漫短剧,AI短剧,短视频制作,AIGC影视全流程应用','http://ishare.ifeng.com/c/s/8tcl0Th10Fz?aman=9n678f370f9a3Mb4bmd0b',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(89,'全省首个OPC社区落地西山区 青年创业迎“AI+”风口',53,'文化创意','宋鹏',41,'90后创业者宋鹏把目光投向银发旅居领域，到上海、苏州、杭州等一线城市学习考察后，带着“银发地陪”的AI项目策划书正式入驻昆明市西山区庾园社区。他依托社区提供的免费办公场地、一对一企业注册服务和AI算力Token资源扶持推进项目落地，继续围绕银发旅居场景打磨服务方案。','地区：云南省 / 昆明市 / 西山区\n案例类型：文化创意\n是否为大学生创新创业：否\n发布日期：2026-04-14','AI项目策划书；AI算力Token资源',NULL,'文化创意,AI项目策划书,AI算力Token资源','https://www.km.gov.cn/c/2026-04-14/5071108.shtml',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(90,'市州动态 | 一人公司，何以出海？贵阳高新区领圈跨境OPC社区的“造船术”',52,'电商营销','赵长省',97,'04年出生的创业者赵长省入驻贵阳高新区领圈跨境OPC社区，在2000平方米实战基地运营一个账号，围绕木质拼接玩具样品开展跨境电商业务。入驻前他受物流成本、税收、运营回报率和产品安全认证困扰；入驻后学习AI工具应用、流量打法转化，并对接高效物流和海外销售渠道。','地区：贵州省 / 贵阳市 / 高新区\n案例类型：电商营销\n是否为大学生创新创业：否\n发布日期：2026-06-10','AI工具应用；流量打法转化；AI赋能与全供应链支撑',NULL,'电商营销,AI工具应用,流量打法转化,AI赋能与全供应链支撑','https://dsj.guizhou.gov.cn/xwzx/szdt/202606/t20260610_90505588.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(91,'市州动态 | 一人公司，何以出海？贵阳高新区领圈跨境OPC社区的“造船术”',52,'电商营销','王发政',97,'00后入驻者王发政进入贵阳高新区领圈跨境OPC社区后，围绕玩具样品测试、短视频素材剪辑、选品和账号运营逻辑开展跨境电商尝试。他借助社区统一拍摄设备理解视频运营逻辑，在产品拍摄、素材剪辑和账号运营上形成自己的思路，准备在供应链和流量支持下推进一人公司式出海业务。','地区：贵州省 / 贵阳市 / 高新区\n案例类型：电商营销\n是否为大学生创新创业：否\n发布日期：2026-06-10','AI赋能与全供应链支撑',NULL,'电商营销,AI赋能与全供应链支撑','https://dsj.guizhou.gov.cn/xwzx/szdt/202606/t20260610_90505588.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(92,'西宁融合创新蓝海就在这里',63,'动漫短剧','蒋程',98,'聚焦AI短剧创作的创业者蒋程入驻西宁北川创新融合发展活力区OPC单人轻创业产业园，在园区扶持下推进数字文创项目。其团队依托办公场地、工位保障和政策扶持深耕西宁数字文创赛道，入驻短短两个月完成两部原创作品落地，并借助园区科教、算力和配套资源继续孵化AI短剧内容。','地区：青海省 / 西宁市 / 北川创新融合发展活力区\n案例类型：动漫短剧\n是否为大学生创新创业：否\n发布日期：2026-07-03','AI短剧创作；数字文创；算力','入驻短短两个月便完成两部原创作品落地','动漫短剧,AI短剧创作,数字文创,算力','https://www.xining.gov.cn/xwdt/jdtp/202607/t20260703_236486.html',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(93,'新疆首个“一人公司”创业孵化平台启动',65,'助农振兴','王进',99,'来自深圳的创业者王进选择与农业相关的智能硬件设备作为创业方向，准备在乌鲁木齐高新技术产业开发区（新市区）OPC创新中心注册“一人公司”。他看重新疆水土光热资源丰富、农业机械化作业面积大，也关注中心共享设备、创业支持和后续科技项目申报便利。','地区：新疆维吾尔自治区 / 乌鲁木齐市 / 高新区（新市区）\n案例类型：助农振兴\n是否为大学生创新创业：否\n发布日期：2026-06-26','智能硬件设备',NULL,'助农振兴,智能硬件设备','https://m.sohu.com/a/1041669346_362042/',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04'),(94,'哈密聚力打造西北AI+创业新高地 OPC社区创新生态大会成功举办',65,'软件开发','艾力·帕拉提（新疆元引智能科技有限公司）',100,'新疆元引智能科技有限公司负责人艾力·帕拉提在哈密开物・碳硅OPC社区创新生态大会上介绍，公司已入驻哈密数字产业园，提供从AI应用开发、大模型私有化部署到数字内容制作、软件定制等全链条服务，契合新疆数字经济发展方向，并面向中小型企业提供智能技术服务。','地区：新疆维吾尔自治区 / 哈密市 / 伊州区\n案例类型：软件开发\n是否为大学生创新创业：否\n发布日期：2026-04-09','AI应用开发；大模型私有化部署；数字内容制作；软件定制',NULL,'软件开发,AI应用开发,大模型私有化部署,数字内容制作,软件定制','https://4g.dahe.cn/news/202604092076138',NULL,'2026-07-08','published','case-excel-import','2026-07-08 10:33:04','2026-07-08 10:33:04');
