--
-- Table structure for table `policies`
--

DROP TABLE IF EXISTS `policies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `policies` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Policy title',
  `region_id` bigint NOT NULL COMMENT 'Related region ID',
  `issuing_body` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Issuing body',
  `document_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Document number',
  `publish_date` date DEFAULT NULL COMMENT 'Publish date',
  `effective_date` date DEFAULT NULL COMMENT 'Effective date',
  `valid_period` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Valid period',
  `source_id` bigint NOT NULL COMMENT 'Main source ID',
  `policy_level` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'national/provincial/city/district',
  `policy_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'comprehensive/computing_support/space_station/funding_subsidy/scenario_demand/talent_service/investment/other',
  `summary` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '100-300 word summary',
  `key_points` text COLLATE utf8mb4_unicode_ci COMMENT 'Key points',
  `support_measures` text COLLATE utf8mb4_unicode_ci COMMENT 'Support measures',
  `tags` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Comma separated tags',
  `original_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Original URL',
  `evidence_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Evidence URL',
  `local_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Local file name',
  `accessed_at` date NOT NULL COMMENT 'Access or download date',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT 'draft/reviewed/published',
  `reviewer` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Reviewer',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Created time',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Updated time',
  PRIMARY KEY (`id`),
  KEY `idx_policies_region_id` (`region_id`),
  KEY `idx_policies_source_id` (`source_id`),
  KEY `idx_policies_policy_type` (`policy_type`),
  KEY `idx_policies_status` (`status`),
  KEY `idx_policies_publish_date` (`publish_date`),
  KEY `idx_policies_effective_date` (`effective_date`),
  KEY `idx_policies_document_no` (`document_no`)
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Policy table';
/*!40101 SET character_set_client = @saved_cs_client */;

