INSERT INTO `policies` VALUES (4,'南宁市人力资源和社会保障局关于服务支持人工智能OPC创业发展十条措施的通知',45,'南宁市人力资源和社会保障局','南人社发〔2026〕8号','2026-04-15','2026-04-15','长期有效',3,'city','comprehensive','南宁出台AI OPC创业十条措施，打造OPC创业社区，提供免费工位/空间、创业奖励、就业补贴、人才补助、算力支持、融资贷款等全链条扶持，打造“AI创业·优选南宁”城市IP，赋能本地产业发展。','政策要点：算力支持,资金补贴,场地工位,人才服务,投资融资,其他\n地区：广西壮族自治区 / 南宁市','【算力支持】\n对OPC企业实际使用算力结算金额的30%给予每年最高200万元的算力支持；鼓励本地算力企业提供免费算力试用、优惠套餐\n\n【资金补贴】\n正常经营满1年的OPC给予5000元创业奖励；高校毕业生创办的OPC经营满18个月再给5000元；带动就业补贴2000元/人；最高1800元创业培训补贴、8000元技能培训补贴\n\n【场地工位】\n给予运营方每年最高20万元服务补贴；入驻创业者每月最高1500元场地水电物业补贴；提供免费创业工位或最高100平方米免费创业空间\n\n【场景需求】\n支持OPC面向东盟应用场景落地，推动企业提质发展，举办创业大赛提供市场拓展支持\n\n【人才服务】\n给予优秀创业团队项目资助、启动资金资助；海外人才薪酬补贴、青年人才生活补助、应届生学费补偿；高层次人才购房补贴、人才公寓优惠；租房补贴、保障性住房等安居政策\n\n【投资融资】\n符合条件的OPC创业者可申请最高30万元、最长3年政府贴息创业担保贷款；小微企业可申请最高400万元、最长2年贴息贷款，贴息后利率低至2.25%\n\n【其他】\n组建OPC创业导师队伍提供全链条服务；提供全流程创业陪跑服务；支持企业申报高新技术企业、专精特新等资质','算力支持,资金补贴,场地工位,人才服务,投资融资,其他','https://www.nanning.gov.cn/ggfw/bmfw/jyfw/zcfg/t6608267.html',NULL,NULL,'2026-07-06','published','excel-import','2026-07-06 00:27:00','2026-07-06 00:27:00'),(5,'五象新区着力打造人工智能OPC创新发展先行区',45,'五象新区（自贸试验区南宁片区）管委会科技创新和产业发展局',NULL,'2026-04-15','2026-04-15','长期有效',4,'district','comprehensive','五象新区出台OPC创新发展十五条措施，从空间载体、算力保障、产品培育、创新创业、人才引育、营商环境六大方面扶持AI一人公司，目标2026年培育5个OPC生态社区，2028年建成20个以上。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他\n地区：广西壮族自治区 / 南宁市 / 五象新区','【算力支持】\n为OPC提供普惠算力服务，对购买算力、消耗Token、调用模型给予一定补贴\n\n【资金补贴】\n对OPC生态社区运营方给予运营奖励；对核心技术创新成果、爆款产品给予奖励；对高校-OPC培养基地运营单位给予奖励\n\n【场地工位】\n支持建设OPC生态社区，提供智能办公设备，帮助创业者实现“拎脑入驻”，对符合条件的社区给予运营奖励\n\n【场景需求】\n支持OPC开发智能体执行工具，推动成果与国产芯片、算力资源协同适配；支持面向东盟国家发展，畅通国际数据通道\n\n【人才服务】\n支持OPC人才申报南宁市“邕江计划”，给予资金配套；符合条件的OPC人才可申请人才公寓；对高校-OPC培养基地运营单位给予奖励\n\n【投资融资】\n发挥政府引导基金、国有资本等作用，构建全周期多元化投融资服务体系；支持产学研用创新联合体建设，促进科技成果转化\n\n【其他】\n为OPC提供全天候全链条全流程服务，开辟注册专属通道，实现电子营业执照远程登记、即时办理；优化营商环境，提供全流程政务服务','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他','http://nnwxxq.gxzf.gov.cn/xxfb/dtzx/t27476362.shtml','https://www.nanning.gov.cn/ywzx/xqdt/2026nxqdt/t6606768.html',NULL,'2026-07-06','published','excel-import','2026-07-06 00:27:00','2026-07-06 00:27:00'),(6,'《辽宁省人工智能OPC培育发展实施方案（2026-2028年）》政策解读新闻发布会',21,'辽宁省发展改革委、省科技厅、省人社厅、省市场监管局、省数据局等',NULL,'2026-05-12','2026-05-12','至2028年12月31日',5,'provincial','comprehensive','辽宁出台OPC培育发展实施方案，2028年目标打造20个以上重点OPC社区、培育300家OPC企业、集聚超3000名人才，从社区建设、招引力度、基础支撑、场景开放、梯度培育、人才培养等方面推进工作。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他\n地区：辽宁省','【算力支持】\n支持基础电信企业提供算网融合服务，鼓励算力供应商推出轻量化算力套餐；沈阳依托六大智算集群提供2265P算力，大连搭建市级算力公共服务平台提供低成本算力\n\n【资金补贴】\n对落地园区的OPC项目给予最高3万元一次性创业奖励；对成效突出的OPC孵化器给予最高200万元资金奖励；各地设立“算力券”“模型券”支持创业\n\n【场地工位】\n依托高新区、青年科创基地、高校创业服务中心等打造专业化OPC社区，提供一站式公共服务平台；沈阳布局浑南科技城、人工智能产业园等OPC社区，大连打造高新区海创、金普新区数谷两大标杆社区\n\n【场景需求】\n完善应用场景全流程服务，推动各级政府、企业发布适配AI场景需求；支持OPC参与场景建设，推动重点细分行业应用推广；沈阳开放数字内容制作、AI算法开发等场景，大连开放政务、企业外包等场景\n\n【人才服务】\n推动高校调整培训内容，开设OPC实践课程、训练营；依托“兴辽英才计划”引进OPC人才；沈阳、大连常态化开展OPC创业培训、技能提升活动；提供人才公寓、生活补贴等安居支持\n\n【投资融资】\n发挥省市各类担保平台作用，鼓励政府投资基金加大支持；沈阳设立科技创新种子基金、成果转化基金；金融机构开发“OPC信用贷”等专属金融产品\n\n【其他】\n优化市场准入服务，提供一站式集成服务，实现企业开办全流程便捷化；加强知识产权保护，推进模型备案和登记；打造OPC“10分钟办公生活圈”；举办创新创业大赛、行业沙龙等活动营造创业氛围','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他','https://www.ln.gov.cn/web/spzb/2026nxwfbh/2026051215571269816/index.shtml','https://fgw.ln.gov.cn/fgw/index/fgfb/2026051310384499171/index.shtml',NULL,'2026-07-06','published','excel-import','2026-07-06 00:27:00','2026-07-06 00:27:00'),(7,'关于印发《大连高新区支持OPC发展若干措施（试行）》的通知',21,'大连高新区管理委员会','大高管规发〔2026〕1号','2026-05-16','2026-06-15','至2028年6月14日',6,'district','comprehensive','大连高新区出台OPC发展若干措施，2026年6月15日起试行，有效期至2028年6月14日，从场地、AI资源、培优、场景、金融、人才、安居、产学研等方面提供全链条扶持，最高补贴可达50万元。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他\n地区：辽宁省 / 大连市 / 高新区','【算力支持】\n按照实际采购额度的50%给予OPC“token加油包”补贴，用于算力服务、模型训练、语料服务等，每家每年最高补贴20万元，按季度兑现\n\n【资金补贴】\n年度遴选入选OPC给予10万元创业资金奖励；场景建设实际投入的35%给予补贴，每家每年最高50万元；对OPC社区运营主体每年最高30万元运营经费补助\n\n【场地工位】\n为符合条件的OPC免费提供不少于3个月的办公工位，配套共享会议室、路演厅、休闲交流区等设施；对优质OPC项目优先提供独立办公空间\n\n【场景需求】\n推动政府公共数据资源依法依规向OPC社区开放；支持OPC参与大厂、大企场景建设，对示范场景项目给予35%投入补贴，每年最高50万元\n\n【人才服务】\n实施“超级训练营”专项计划，免费提供AI技术、创业实战等系统培训；建立OPC创业人才库，优先推荐申报各级创业人才项目\n\n【投资融资】\n为符合条件的OPC提供不超过1000万元的投资；对获得贷款的OPC，按1%年化利率给予利息补贴，每个年度最高30万元；对省级以上赛事获奖项目给予天使基金支持\n\n【其他】\n为符合条件的OPC人才提供区内人才公寓，享受租金优惠和安居补贴；配备技术经理人，提供免费技术需求诊断、成果转化、产学研对接等服务；常态化组织技术对接会、成果推介会等活动','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他','https://www.dlhitech.gov.cn/policy/view_2c8585ab9e2affda019e39bf77ab0003.html','https://www.dlhitech.gov.cn/news/view_79120.html',NULL,'2026-07-06','published','excel-import','2026-07-06 00:27:00','2026-07-06 00:27:00'),(8,'《保定市支持人工智能OPC创新发展的若干措施》',13,'保定市数据局',NULL,'2026-04-08',NULL,'有效期2年',7,'city','comprehensive','保定市发布OPC创新发展若干措施征求意见稿，提出11条扶持举措，从孵化载体、数据要素供给、安全保障、模型研发、数据服务、场景应用、创客集聚、人才服务、金融服务、创业培训等方面提供支持，有效期2年。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他\n地区：河北省 / 保定市','【算力支持】\n对采购算力、数据及大模型、智能体等技术与服务年度总额30万元以上的，按实际支出30%给予最高30万元“数智券”支持\n\n【资金补贴】\n对认定的OPC孵化载体给予最高30万元支持；离校2年内高校毕业生首次创办OPC正常运营1年以上的，给予5000元一次性创业补贴；提供不高于20万元的科技创新券支持\n\n【场地工位】\n鼓励设立“数创港”吸引OPC入驻，为入驻OPC提供一年免费办公场地，配套智能体开发工具、测试环境、开发实训、合规指导等服务\n\n【场景需求】\n支持OPC参与公共数据授权运营，开发交通、医疗、城市治理等领域高价值脱敏公共数据；在政务、医疗、教育、文旅等重点领域开展应用示范，对示范项目给予“数智券”支持\n\n【人才服务】\n将OPC人才纳入保定市人才认证体系，享受相关人才政策；高层次人才优先申报省市级人才评选；新引进的“双一流”人才可申请10-30万元购房补贴或每月1500-3500元租房补贴；其他博士、硕士可享受10-15万元购房补贴或每月1500-2000元租房补贴\n\n【投资融资】\n对符合条件的OPC提供不超过30万元个人创业担保贷款；引导银行开发专属信贷产品；发挥政府产业引导基金作用，撬动社会资本投向OPC\n\n【其他】\n编制《OPC知识产权生存手册》，提供全流程指引与服务保障；建立OPC信用评价体系，实施信用分级监管；实施“蒲公英：OPC百场万人培训”计划，提供职业技能培训补贴；开辟OPC注册专属通道，实现“一窗受理、并联办理、即时办理”','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他','https://baoding.gov.cn/content-159-538877.html','https://www.hebgcdy.com/dfpd/system/2026/03/27/030935202.shtml',NULL,'2026-07-06','draft','excel-import','2026-07-06 00:27:00','2026-07-06 00:27:00'),(9,'关于印发山西省促进先进算力与人工智能融合发展若干措施的通知',14,'山西省人民政府办公厅','晋政办发〔2024〕35号','2024-06-25','2024-07-01','至2026年12月31日',8,'provincial','comprehensive','山西出台算力与人工智能融合发展若干措施，2024年7月1日起施行，有效期至2026年12月31日，支持算力高质量发展、算力应用水平提升、AI大模型发展，出台“算力券”政策，每年发放不超过5000万元，支持企业、高校、科研机构使用算力资源。','政策要点：算力支持,资金补贴,场景需求,人才服务,其他\n地区：山西省','【算力支持】\n出台“算力券”政策，每年发放总额不超过5000万元，对符合要求的申领主体，按算力服务合同金额的20%给予总额不超过100万元奖励；对国家级重大项目或大模型研发主体，按合同金额30%给予最高200万元奖励\n\n【资金补贴】\n对新建智算中心项目，按软硬件设备实际投资的15%给予最高5000万元补贴，给予贷款最高2%贴息补助，补贴期不超过2年；对云服务收入占比达标企业，按每个物理机架最高1000元给予总额最高300万元一次性补贴；对边缘计算中心、绿色数据中心、自主可控数据中心给予最高30-500万元不等补贴\n\n【场景需求】\n支持算力应用场景创新，每年评选10个优秀算力应用示范场景，按关键设备和系统软件投入的20%给予最高100万元一次性奖励；支持行业大模型研发与产业化应用，对形成商用案例的给予最高100万元一次性奖励\n\n【人才服务】\n鼓励高校开设算力和人工智能相关专业，对依托相关领域国家级、省级一流专业创建教学实践培训基地的，择优一次性给予最高200万元补贴\n\n【其他】\n支持算力调度和监测平台建设，按平台投资额10%且最高不超过200万元给予补助；支持算力资源对外输出，对年度省外算力服务合同总额达到2亿元及以上的企业，按合同总额的2%给予最高1000万元奖励；支持AI大模型关键技术攻关，对符合条件的大模型给予研发总投入20%、最高1000万元补贴','算力支持,资金补贴,场景需求,人才服务,其他','https://www.shanxi.gov.cn/zcwjk/bgtwj/202411/W020241126419735939730.pdf',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:30:59','2026-07-06 00:30:59'),(10,'大同市OPC社区建设专项扶持政策',14,'大同市就业创业服务中心、大同数据科技职业学院',NULL,'2026-03-28','2026-03-28','长期有效',9,'city','comprehensive','大同打造山西省首家OPC社区，依托本地绿电算力优势，为AI一人公司提供大厂级算力支撑、一站式创业服务、全链条产业对接，助力“一人成军”的超级个体创业落地。','政策要点：算力支持,场地工位,人才服务,其他\n地区：山西省 / 大同市','【算力支持】\n依托本地绿电算力优势，为OPC提供大厂级算力支撑，降低AI创业算力成本\n\n【场地工位】\n打造OPC社区，提供配套办公空间、共享设施，为AI一人公司提供一站式创业服务场地支持\n\n【场景需求】\n提供全链条产业对接服务，助力OPC对接本地产业场景，推动AI技术落地应用\n\n【人才服务】\n联合职业学院提供AI技能培训、创业培训，为OPC创业提供人才支撑\n\n【其他】\n提供全流程创业孵化服务，包括创业指导、产业对接、资源链接等，助力超级个体创业落地','算力支持,场地工位,人才服务,其他','http://www.dt.gov.cn/dtszf/tuidonggaozhiliang/202603/bceb2cdbec7947e6ad44b181a7ef6056.shtml','http://epaper.dtnews.cn/dtrb/html/2026-05/13/content_2_288050.htm',NULL,'2026-07-04','published','excel-import','2026-07-06 00:30:59','2026-07-06 00:30:59'),(11,'《无锡市人工智能OPC企业登记便利化工作服务指引（试行）》',32,'无锡市市场监督管理局、无锡市数据局',NULL,'2026-06-16','2026-06-09','长期有效',10,'city','comprehensive','无锡发布OPC企业市场准入便利化服务指引，打造六大闭环服务链条，推出四项便利化举措，提供OPC社区备案、集群注册、数据知识产权辅导、确权数据作价入股等服务，配套专属金融产品、知识产权全链护航。','政策要点：投资融资,其他\n地区：江苏省 / 无锡市','【场地工位】\n依托无锡（国家）软件园魔方空间OPC社区，提供集群注册托管服务，免住所权属材料\n\n【投资融资】\n交通银行无锡分行推出“OPC创业贷”，单户授信最高3000万元，年化利率低至2.4%起，期限最长10年，支持信用、知识产权质押等多种担保方式\n\n【其他】\n推出OPC社区备案极简办、集群注册一站落户、数据知识产权全流程辅导、确权数据可作价入股四项便利化举措；提供数据知识产权登记辅导、专利布局与高价值培育、全维度风险防控、常态化驻点服务等知识产权全链护航服务','投资融资,其他','https://scjgj.wuxi.gov.cn/doc/2026/06/16/4791426.shtml','https://scjgj.wuxi.gov.cn/doc/2026/04/21/4766681.shtml',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:00','2026-07-06 00:31:00'),(12,'市政府办公室印发关于支持人工智能OPC创新发展的十条举措的通知',32,'常州市人民政府办公室','常政办发〔2026〕12号','2026-05-25','2026-05-09','长期有效',11,'city','comprehensive','常州出台OPC创新发展十条举措，聚焦五大要素保障、五大环境营造，打造长三角OPC创业高地，从场景开放、资金保障、人才支撑、公共算力支持、平台载体赋能等方面提供全链条扶持。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他\n地区：江苏省 / 常州市','【算力支持】\n鼓励OPC租用常州市公共算力调度平台智能算力，按规定给予算力补贴；提供模型推理服务平台，每个模型可免费使用部分词元；依托城市可信数据空间，分类分级开放脱敏公共数据和行业数据集，对购买数据集产品的OPC给予补贴\n\n【资金补贴】\nOPC企业纳入“苏科贷”、创业担保贷款及一次性创业补贴范围，符合条件的个人可申请最高50万元创业担保贷款并享受贴息；对购买OPC技术成果的企业，最高可享受30万元奖励；对OPC标杆社区每年给予最高500万元专项补贴\n\n【场地工位】\n鼓励创新创业载体设立OPC专项孵化单元，打造20万平方米OPC专属空间，打造10家以上专业OPC标杆社区；鼓励园区提供零租工位、拎包入驻服务，配套共享会议室、路演厅、直播间等公共设施\n\n【场景需求】\n2026年推出不少于100个AI应用场景，鼓励OPC参与场景开发；打造“常州OPC智能体超市”，促进OPC技术成果转化应用；支持链主企业开放供应链资源、市场渠道，为OPC提供订单支持\n\n【人才服务】\n在重点产业紧缺人才目录中单列OPC人才类别，高层次领军创业人才给予最高1000万元综合资助；试点建设OPC人才培育基地，开设模块化课程，每年培训不少于500人次复合型创业人才；OPC创业者优先纳入“龙城英才计划”，享受人才公寓、购房补贴等礼遇\n\n【投资融资】\n鼓励各级政府投资基金设立OPC专项基金，中以常州创新园1亿元OPC基金对单个直投项目最高可实行100%风险容忍，基金存续期最高可延长至15年；鼓励金融机构推出OPC专属创业贷款产品，降低准入门槛、优化审批流程\n\n【其他】\n推行OPC“一类事”改革，在政务服务中心设立“OPC服务专窗”，提供一站式办理服务，0.5个工作日办结；设立OPC政策专栏，推动政策智能匹配与“免申即享”；建立“创业搭子”配对机制，打造“OPC Club”，每年举办不少于20场社交活动；制定行业伦理准则，完善知识产权保护，建立快速维权通道','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他','https://www.changzhou.gov.cn/gi_news/425177967890000',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:00','2026-07-06 00:31:00'),(13,'市政府办公室关于印发宿迁市加快推进OPC创新发展十条政策措施的通知',32,'宿迁市人民政府','宿政办规〔2026〕1号','2026-02-05','2026-03-08','至2028年12月31日',12,'city','comprehensive','宿迁出台OPC创新发展十条政策，2026年3月8日起实施，有效期至2028年12月31日，目标打造全国知名OPC创业之城，从数据要素供给、初创成本降低、创新激励、平台工具搭建、金融支持、空间配套、人才培育、生态打造等方面提供扶持。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他\n地区：江苏省 / 宿迁市','【算力支持】\n按“基础免费+进阶补贴”模式，为OPC提供算力、网络、云空间等共性资源，基础范围内首年免费，进阶需求按实际费用30%阶梯式补助，总计不超过100万元的“算力券”“模型券”“云网券”包\n\n【资金补贴】\n对OPC采购数据产品的，按年度交易金额20%给予“数据券”补贴，每年最高50万元；对OPC购买法律、审计、知识产权等服务的，一次性给予最高5万元“服务券”补贴；对列入省重点推广的新技术新产品目录的给予最高10万元奖励；对国家级、省级优秀场景案例分别给予最高100万元、30万元奖励；对首次完成国家级生成式AI模型备案的给予最高50万元一次性奖励，累计最高200万元；对营收首次达2000万元的奖励5万元；对认定的省级数据企业给予最高10-50万元一次性奖励；对国家级、省级创新创业大赛获奖项目最高分别奖励50万元、20万元\n\n【场地工位】\n全市建成20个以上、总面积不低于10万平方米的标杆OPC社区，提供共享工位、胶囊工位、独立空间等多样化选择，配套会议室、路演厅、直播间等共享商务空间；打造OPC“10分钟办公生活圈”；对OPC社区运营主体按绩效给予最高40万元奖励\n\n【场景需求】\n公布“人工智能+”应用场景开放清单、机会清单，通过“揭榜挂帅”模式鼓励OPC对接场景需求；支持OPC参与数据资源开发利用，对数据产品挂牌交易的按交易金额10%给予每年最高50万元奖励\n\n【人才服务】\n建设OPC人才培育示范基地，开设“OPC创业实战营”，定期举办创享课堂、专场路演等活动；单场培训活动最高补贴10万元，每个承办主体年度补贴不超过30万元；对OPC项目负责人给予市人才政策相关生活补贴、科研补贴、购房补贴等支持\n\n【投资融资】\n用好三台山人才基金，设立OPC专项金融产品，优化轻资产企业融资准入门槛；对OPC支付的贷款利息，按同期LPR最高50%给予补贴，每年最高200万元；鼓励各类基金投早、投小、投长期，投向OPC创业项目\n\n【其他】\n打造“宿迁OPC工具栈”，整合智能工具、开发平台、大模型等资源，满足OPC创业高频需求；支持建设OPC公共服务平台，按绩效给予累计不超过30万元奖励，对国家级、省级示范平台分别给予最高100万元、50万元奖励；探索利用上海、苏州等“科创飞地”开展OPC创新创业；建立OPC创业联盟，单场生态活动最高补贴10万元，每个承办主体年度补贴不超过30万元；推行OPC“一类事”改革，提供一站式创业服务，实现“一日开办”；设立OPC专栏，提供政策查询、兑现、诉求反馈等功能，建立常态化政企沟通机制','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他','https://suqian.gov.cn/cnsq/xzgfwj/202602/3a94b92a87c34ad5bd09b0e3722f0009.shtml','https://www.suqian.gov.cn/zfb/zcfg/202602/4a3a45ec9a484fd4bdc07f3e9ac4f867.shtml',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:00','2026-07-06 00:31:00'),(14,'苏州市进一步加快建设“人工智能+”城市的若干措施(2026年版)',32,'苏州市人民政府','苏府规字〔2025〕18号','2025-12-30','2026-01-31','至2027年1月30日',13,'city','comprehensive','苏州出台2026版人工智能+城市建设措施，支持OPC社区建设，发放算力券、语料券，提供算力补贴、研发奖励、人才资助、金融支撑等全链条扶持，打造AI一人公司创业生态。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他\n地区：江苏省 / 苏州市','【算力支持】\n对符合条件的科技研发企业，按实际支付智能算力租用费用的30%给予每年最高200万元补贴；向OPC创业者发放最高100%支持的20万元算力券\n\n【资金补贴】\n对高质量数据集及语料库给予最高200万元奖励；对模型研发、场景应用、标准研制等给予最高2000万元资金支持；对OPC主题大赛按投入50%给予最高200万元补贴\n\n【场地工位】\n加快推进人工智能产业载体建设，打造一批高品质、低成本的OPC社区，提供配套公共服务\n\n【场景需求】\n每年遴选一批人工智能应用场景项目，按采购额30%给予最高200万元奖励；支持建设场景开放创新中心，三年总计最高300万元支持\n\n【人才服务】\n对新引进的人工智能领域急需紧缺专业全日制应届博士、硕士、本科生分别给予10万元、3万元、1万元一次性生活补贴；对领军人才给予最高500万元项目资助\n\n【投资融资】\n鼓励社会资金建立人工智能产业基金；对企业科技贷款利息、科技保险保费按政策予以补贴；对科技信贷损失给予最高1000万元风险补偿\n\n【其他】\n支持OPC社区建设，每年评定市级人工智能产业园给予200万/100万补助；支持举办OPC主题大赛、行业交流活动；鼓励AI标准研制，给予最高100万元资助','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他','http://www.suzhou.gov.cn/szsrmzf/szfgfxwjk/202512/859f7ff48e8d45fdb9f38ad5977294ac/files/c183c2daa8954f7c9bc6fe9a25cae09f.pdf','http://www.suzhou.gov.cn/szsrmzf/szfgfxwjk/202512/859f7ff48e8d45fdb9f38ad5977294ac.shtml',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:01','2026-07-06 00:31:01'),(15,'常熟市关于加快打造青年友好型OPC创业社区的若干措施',32,'常熟市人民政府','无','2026-01-06','2026-01-06','长期有效',14,'city','comprehensive','常熟出台青年友好型OPC创业社区措施，打造10个以上超百万平方米OPC专业社区，提供30天免费办公住宿餐饮礼包，配套算力补贴、人才安居、全链创业服务，降低AI一人公司创业门槛。','政策要点：算力支持,资金补贴,场地工位,人才服务,其他\n地区：江苏省 / 常熟市','【算力支持】\n高质量数据集及语料库相关OPC最高可获200万元奖励；智能算力租用补贴最高达200万元\n\n【资金补贴】\n入选上级顶尖人才计划的OPC项目给予最高1亿元支持；入选上级“双创团队”的OPC项目给予最高1000万元配套资助\n\n【场地工位】\n打造10个以上总面积超百万平方米的OPC专业社区，提供拎包入驻服务；对符合条件的入驻OPC推出最高30天免费办公、住宿、餐饮“三重礼包”\n\n【场景需求】\n聚焦具身智能、纺织服装等特色领域，打造垂直场景应用\n\n【人才服务】\n构建分层人才培育体系，给予人才安居补贴；推出“常来沪往”高铁补贴，加速跨区域人才互通\n\n【投资融资】\n常态化开展投融资对接活动，为OPC提供融资对接服务\n\n【其他】\n构建“线上+线下”一体化服务矩阵，打造OPC一站式服务平台，提供政策咨询、企业注册、法务等全要素服务；常态化举办行业沙龙、创业培训等活动','算力支持,资金补贴,场地工位,人才服务,其他','https://www.suzhou.gov.cn/szsrmzf/qxkx/202601/5e527f626302481ba1000a638893e36c.shtml','https://www.changshu.gov.cn/zgcs/c108209/202601/b44d477100cc404286cf10be78f81b2e.shtml',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:02','2026-07-06 00:31:02'),(16,'苏州工业园区关于加快打造全球领先的人工智能OPC创业首选区的若干措施',32,'苏州工业园区管理委员会','无','2025-11-27','2025-11-27','长期有效',15,'district','comprehensive','苏州工业园区发布OPC专项措施，打造10个以上百万平方米OPC标杆社区，提供算力补贴、研发补助、人才专项支持、10亿元青创基金群，打造全球领先的AI一人公司创业首选区。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他\n地区：江苏省 / 苏州市 / 工业园区','【算力支持】\n建设统一调度的公共算力共享池，提供即开即用算力服务；对符合条件的OPC，按实际支付算力费用的20%给予每年最高200万元支持；对高质量数据集每个给予最高10万元奖励\n\n【资金补贴】\n对符合条件的OPC给予研发投入补助，每年最高200万元；对采购高质量数据集、语料库按合同额30%给予最高30万元采购支持，每年最高100万元；对社区运营主体每年最高200万元运营奖励\n\n【场地工位】\n打造10个以上、总面积≥100万㎡的OPC标杆社区，提供拎包入驻服务，租金减免/零租工位，配套完善生活设施，构建10分钟办公生活圈\n\n【场景需求】\n系统梳理并开放一批高价值产业场景，为OPC提供技术落地试验田；鼓励园区企事业单位对OPC新技术新产品首试首用\n\n【人才服务】\n在“金鸡湖科技领军人才工程”中单设OPC专项，单个项目最高可获得5000万元支持；提供启动资金、房票补贴、生活补助等人才组合式支持\n\n【投资融资】\n设立规模10亿元的“青创基金群”，对优质OPC项目给予最高2000万元政策性股权投资；鼓励银行设专项信贷产品，贷款利息最高50%补贴，年最高200万元、最长3年\n\n【其他】\n支持举办OPC大赛、展会、产学研对接会等生态活动，按活动总支出30%给予最高200万元支持；提供全周期创业辅导、法务、财税等一站式服务','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他','https://www.sipac.gov.cn/szgyyq/dthg202511/202511/981072392d0c417ab460af65ed3b2495.shtml','https://sst.suzhou.gov.cn/ndaservplat/Apps/psp/index.php?s=%2FHome%2FEpAppPolicySearch%2Fpolicydetail%2Fid%2F113193',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:02','2026-07-06 00:31:02'),(17,'宁波市人民政府办公厅关于支持人工智能OPC创新创业发展的若干意见（甬政办发〔2026〕7号）',33,'宁波市人民政府办公厅','甬政办发〔2026〕7号','2026-05-11','2026-05-21','至2028年12月31日',16,'city','comprehensive','宁波出台OPC专项意见，目标2028年集聚超1万名OPC创业者，建设10个以上市级OPC社区，提供算力补助、科创消费券、人才安居补贴、创业担保贷款等全链条扶持，打造OPC滨海创业之都。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他\n地区：浙江省 / 宁波市','【算力支持】\n统筹全市算力基础设施，为OPC提供轻量化、低成本算力服务；按不超过算力、语料、模型合同执行金额的30%给予最高800万元补助；支持各区为OPC社区入驻用户提供定额免费算力服务\n\n【资金补贴】\n发放科创服务消费券，给予最高20万元补助；发放场地租赁等创新创业消费券，给予最高5万元补助；对数据产品交易按规定给予最高35万元奖励；对OPC社区每年给予最高200万元分档补助\n\n【场地工位】\n支持盘活存量楼宇打造OPC社区，嵌入式布局OPC专区；提供低成本“AI工位”，配套登记注册、财务代账等公共服务；支持“工位号”登记、一址多照，提供共享办公空间\n\n【场景需求】\n开放政府、国有企业和龙头企业场景资源；支持通过合作创新采购对OPC新技术新产品首购、订购；开放医疗、交通、文旅等领域高质量脱敏公共数据\n\n【人才服务】\n支持OPC创业者申报“甬江人才工程”，入选项目给予最高100万元资助；新引进高层次OPC人才享受最高60万元购房补贴、最高300万元安居补贴；新引进毕业一年内OPC人才享受每月1000元、最长60个月安居补贴\n\n【投资融资】\n支持天使投资引导基金加大对OPC早期项目投资，对股权投资机构投资初创期OPC按实际投资额10%给予奖励；符合条件的OPC创业者可申请最高50万元创业担保贷款，享受财政贴息；为首次在甬创业的OPC创业者投保创业保险，最高6万元创业补助\n\n【其他】\n设立线上OPC服务专区，提供一站式服务；实施包容审慎监管，试点“沙盒监管”模式；加强OPC知识产权保护，提供数据知识产权登记服务；支持成立OPC创新创业联盟，常态化举办创业大赛、沙龙等活动','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他','https://www.ningbo.gov.cn/col/col1229897207/2026nd08q/art/2026/art_80c60df8a10541a99ff41283b5928e9d.html','https://www.ningbo.gov.cn/col/col1229096002/art/2026/art_9fe8f547ad2144b3a811a8efa4c539e0.html',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:03','2026-07-06 00:31:03'),(18,'温州市关于加快打造人工智能OPC创业高地的若干举措',33,'温州市委教育科技人才一体化委员会办公室','无','2026-03-25','2026-03-19','长期有效',17,'city','comprehensive','温州出台全省首个市级OPC政策，推出17条举措，目标2028年引育超2万名OPC创业人才、超1万家OPC，建设10个以上OPC主题社区，提供算力券、免费工位、人才安居、极简注册等扶持。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他\n地区：浙江省 / 温州市','【算力支持】\n建设市人工智能一体化平台，推出智能编程、数字人制作等AI工具箱；OPC可申领“算力券、模型券、语料券”降低研发成本\n\n【资金补贴】\n落实创业补贴、免费刻章、证照寄递等惠企服务；对技术交流活动给予费用补贴\n\n【场地工位】\n打造10个以上OPC主题社区，提供“拎包入驻”创业空间，构建“一张办公桌、一间办公室、一层办公楼”孵化体系\n\n【场景需求】\n开放制造业场景需求，搭建OPC与规上企业对接桥梁，支持OPC“揭榜”承接数字化“微订单”；开放公共数据与政务、教育、文旅等应用场景，支持OPC优先参与招标采购\n\n【人才服务】\n建设人工智能人才培养基地，开展AI+系列技能培训；建立开放多元人才评价体系，符合条件的OPC核心成员可直接认定D类、E类人才；将OPC创业者纳入“青年安居计划”，解决居住需求\n\n【投资融资】\n政府产业基金专设OPC专项池；银行保险机构加大信贷、保险支持，提供专属金融产品\n\n【其他】\n推行OPC“一窗受理、一日办结”极简注册，设立服务专窗；实施“首席法务经理”制度，提供首年免费基础法务服务；建立知识产权快速保护通道；探索柔性监管与“预约式”行政指导；常态化举办OPC创业赛事、行业沙龙等活动','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他','https://wzszsh.wenzhou.gov.cn/col/col1229457173/art/2026/art_ca407fe1bc4c4304951b873e623ca9ab.html','无',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:04','2026-07-06 00:31:04'),(19,'杭州市市场监督管理局关于支持一人公司OPC创新创业发展的若干举措',33,'杭州市市场监督管理局','杭市监〔2026〕43号','2026-04-15','2026-04-15','长期有效',18,'city','comprehensive','杭州出台OPC扶持举措，聚焦注册登记、行政指导、知识产权保护、信用赋能、执法监管五大维度，提供极简审批、陪伴式成长服务、知识产权一站式保护、信用融资、包容审慎监管等全周期服务。','政策要点：其他\n地区：浙江省 / 杭州市','【算力支持】\n无\n\n【资金补贴】\n无\n\n【场地工位】\n支持OPC创业园区发展，按规定实施“一址多照”“工位注册”，提供低成本共享办公空间\n\n【场景需求】\n支持OPC公平参与人工智能模式创新、场景应用等领域标准制定\n\n【人才服务】\n无\n\n【投资融资】\n实施OPC信用融资行动，开发专属无抵押信用贷款产品；支持OPC知识产权质押融资、证券化\n\n【其他】\n打造市场准入快速通道，提供全程网办“零成本”市场准入服务；支持OPC以知识产权、数据等非货币财产作价出资；建立OPC陪伴式服务机制，提供全流程指导帮扶；编制发布“入市陪伴手册”，提供合规指导；加强OPC商标品牌、商业秘密、人工智能领域知识产权保护，开辟专利审查绿色通道；实施OPC信用风险柔性管理，降低抽查比重，推行“多报合一”智能年报；推行包容审慎执法监管，落实首违不罚、轻微免罚清单；在OPC社区探索“沙盒监管”模式','其他','https://zfgb.hangzhou.gov.cn/upload/default/bigfile/2026/04/15/20260415_ef3cc7422f3a5f0c1043eb59c87d6026.pdf','无',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:04','2026-07-06 00:31:04'),(20,'慈溪市支持人工智能OPC发展推动产业高质量发展的若干措施',33,'慈溪市人民政府办公室','无','2026-06-03','2026-06-01','至2026年12月31日',19,'city','comprehensive','慈溪出台OPC发展措施，从十大方面构建扶持体系，提供算力补助、数据服务、OPC社区建设补贴、人才安居、创业落地支持、专属信贷等扶持，有效期至2026年12月31日。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他\n地区：浙江省 / 慈溪市','【算力支持】\n依托市级算力平台提供低成本国产算力，给予最高100万元算力补助；对企业购买语料、模型给予30%最高100万元补助\n\n【资金补贴】\n对智能体部署平台给予最高300万元专项补贴；对企业智能体解决方案投入给予最高200万元补贴；对优秀AI应用场景、数据产品建设给予最高30万元奖励；对OPC社区优秀运营主体给予最高150万元运营补贴；对创新创业大赛获奖团队给予资金奖励，对技术交流活动给予50%最高5万元费用补贴\n\n【场地工位】\n鼓励建设特色产业OPC社区，纳入孵化器政策支持；提供30天免费办公食宿，最长2年办公空间优惠期\n\n【场景需求】\n开放公共脱敏数据，提供全流程数据咨询服务；推动智能体在制造业场景应用，支持工业大模型攻关\n\n【人才服务】\n提供最高15万元安居补贴、20万元购房补贴；对人才项目给予最高1000万元综合支持；提供高铁补贴等交通出行支持\n\n【投资融资】\n提供OPC专属信贷、保险补贴等金融服务\n\n【其他】\n建立店小二代办员机制、设立OPC服务专窗，推行“零门槛”登记、“一址多照”等举措；推出智能制造智能体专属认证服务，对服务商按服务企业数给予每家最高1万元支持','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他','https://zhengce.zj.gov.cn/policyweb/httpservice/showinfo.do?infoid=b620fc166ddf29849d1437c45cba17d9','无',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:05','2026-07-06 00:31:05'),(21,'安徽省打造通用人工智能产业创新和应用高地若干政策（2.0版）',34,'安徽省人民政府','皖政秘〔2025〕108号','2025-08-21','2025-08-11','至2027年12月31日',20,'provincial','comprehensive','安徽出台通用人工智能产业2.0版政策，支持OPC相关的场景开放、算力补贴、模型研发、人才保障、金融支撑，对相关项目给予最高1000万元支持，有效期至2027年12月31日。','政策要点：算力支持,资金补贴,场景需求,人才服务,投资融资,其他\n地区：安徽省','【算力支持】\n升级完善省级智能算力统筹调度平台；对算力使用方给予不超过算力总支出20%的支持\n\n【资金补贴】\n对场景创新项目给予不超过场景开发投入20%、最高1000万元支持；对优秀场景应用案例给予最高100万元支持；对省级通用人工智能产业创新园区给予最高500万元奖励；对全国大赛获奖落地项目最高支持3000万元\n\n【场地工位】\n支持各地建设通用人工智能产业创新园区，给予最高500万元奖励\n\n【场景需求】\n每年发布一批应用场景创新重点任务并组织“揭榜挂帅”，对揭榜成功项目给予最高1000万元支持；支持建设科学研究领域人工智能应用基地，给予最高1000万元支持；支持通用人工智能创新产品申报省“三首”产品，在招投标和政府采购中优先采购\n\n【人才服务】\n对符合条件的人工智能领域企业创始人、核心骨干，开辟人才认定绿色通道；加大对青年人才和创新创业团队支持\n\n【投资融资】\n加快运营总规模不低于200亿元的省人工智能产业主题基金，支持设立子基金，满足OPC等初创企业资金需求\n\n【其他】\n支持通用人工智能领域核心技术攻关，设立AI青年科学家项目指南；举办通用人工智能创新应用全国大赛；以政府购买服务方式组织开展人工智能领域培训、推介活动','算力支持,资金补贴,场景需求,人才服务,投资融资,其他','https://www.ah.gov.cn/public/1681/565449701.html','无',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:05','2026-07-06 00:31:05'),(22,'合肥高新区打造人工智能OPC创业生态示范区行动计划实施细则',34,'合肥高新区管委会、合肥市大数据资产运营有限公司','无','2026-05-18','2026-05-18','长期有效',21,'district','comprehensive','合肥高新区上线OPC创业者平台，汇聚超2.5万PB公共算力资源，接入国内主流大模型，配套算力补贴政策，按算力实际支付费用的20%发放补贴，单个企业最高1000万元，赋能AI一人公司创业。','政策要点：算力支持,其他\n地区：安徽省 / 合肥市 / 高新区','【算力支持】\n平台汇聚公共算力资源超2.5万PB，提供裸金属整机租用、弹性算力及HPC超算资源三大类服务；按算力资源实际支付费用的20%发放算力补贴，单个企业最高补贴额度达1000万元\n\n【资金补贴】\n无\n\n【场地工位】\n无\n\n【场景需求】\n无\n\n【人才服务】\n无\n\n【投资融资】\n无\n\n【其他】\n平台全面接入国内所有主流大模型，满足全品类AI应用需求；实现从认证到结算的全流程线上作业，提供按需付费、资费明细查询等服务；配套OPC企业备案、模型调用、费用结算等全流程服务','算力支持,其他','https://gxq.hefei.gov.cn/xwdt/qyxw/18945487.html','https://vt.quark.cn/blm/quark-doc-main-pc-966/preview?fp_from=sc&id=E84B9FB750C0852E21468C14C92E471D',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:06','2026-07-06 00:31:06'),(23,'庐阳区人工智能OPC创业优选区培育发展三年行动计划（2026-2028年）',34,'合肥市庐阳区人民政府','无','2026-04-25','2026-04-25','至2028年12月31日',22,'district','comprehensive','合肥庐阳区发布OPC三年行动计划，构建“1+3+N”全域OPC创业矩阵，开放首批30个OPC微场景，提供零成本启动工位、算力调度平台、人才绿色通道、全周期创业服务，打造AI一人公司创业优选区。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他\n地区：安徽省 / 合肥市 / 庐阳区','【算力支持】\n搭建统一算力调度平台，为OPC提供专项算力支持\n\n【资金补贴】\n无\n\n【场地工位】\n打造2个OPC社区，提供零成本启动工位，布局N个分布式OPC微社区，提供低成本创业空间\n\n【场景需求】\n开放首批30个OPC微场景机会清单，覆盖六大领域，采用“订单驱动”模式，让OPC拿着订单创新\n\n【人才服务】\n为OPC创业者及核心人才开通落户、住房、医疗、子女就学绿色通道\n\n【投资融资】\n常态化开展投融资路演与项目对接活动，为OPC搭建资本桥梁\n\n【其他】\n构建“1+3+N”全域人工智能OPC创业矩阵，打造1个核心开源社区、3个垂直场景赋能基地、N个分布式微社区；提供全周期创业辅导、法务、财税等一站式服务；常态化举办OPC创业赛事、行业交流活动','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资,其他','https://kjt.ah.gov.cn/kjzx/mtjj/123368961.html','http://ah.news.cn/20260428/7f9db2ae99604bb89a3566bd53f80fb1/c.html',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:06','2026-07-06 00:31:06'),(24,'厦门市思明区 OPC 企业开办 “一类事” 服务',35,'厦门市思明区市场监督管理局、思明区工业园区管理委员会',NULL,'2026-05-13','2026-05-13','长期有效',23,'district','comprehensive','思明区全省率先推出OPC企业开办“一类事”集成服务，融合政务联办、AI特色服务、增值生态配套三大板块，实现一次申请、全程帮办，配套OPC共生社区全要素支撑，助力AI一人公司零门槛落地。','政策要点：其他\n地区：福建省 / 厦门市 / 思明区','【算力支持】\n整合算力服务、人工智能产业公共服务平台，匹配AI创业核心算力需求\n\n【场地工位】\n提供未来科技园、超级合子OPC共生社区等创业空间，配套共享工位\n\n【其他】\n1.集成企业开办、开业即开票、个人创业一件事，一次提交同步联办；2.线上线下双渠道办理，1个工作日内专员对接全程跟踪；3.提供集群注册地址、法律、金融、数据等全周期增值服务；4.开展数字化工具培训，赋能轻创业提质增效','其他','https://www.siming.gov.cn/xxgk/xwgg/gzdt/202605/t20260513_1147842.htm',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:07','2026-07-06 00:31:07'),(25,'泉州市丰泽区人民政府办公室关于印发《丰泽区加快建设OPC创业首选区行动计划（2026－2028年）》的通知',35,'泉州市丰泽区人民政府办公室','泉丰政办综〔2026〕6号','2026-03-25','2026-03-25','至2028年12月31日',24,'district','comprehensive','丰泽区出台OPC创业首选区三年行动计划，实施“十百千万”工程，从孵化空间、梯队培育、算力底座、数据供给、场景开放、融资渠道、人才支撑、权益保障八大方面，打造全国知名OPC创业首选区。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资\n地区：福建省 / 泉州市 / 丰泽区','【算力支持】\n1.建设人工智能赋能OPC创业公共服务平台，集成OPC工具栈，开放各类大模型、行业垂直模型工具包；2.按“基础免费+进阶补贴”模式，对OPC使用算力、模型、云网资源给予算力补贴\n\n【资金补贴】\n1.统筹各级资金用于OPC社区运营、孵化中心建设补贴及创业项目奖励、赛事举办；2.对OPC购买法律、财税、知识产权等服务给予服务补贴；3.每年评选10个优质数据产品给予奖励\n\n【场地工位】\n1.高标准建设OPC社区，配置多样化工位、共享商务空间，提供零租工位、人才公寓；2.依托OPC社区设置创业服务驿站，提供一站式服务；3.允许符合条件的市场主体“一址多照”和集群注册\n\n【场景需求】\n1.定期发布应用场景开放清单、机会清单，聚焦影视文化、电子商务、数字营销等领域开放场景；2.通过“揭榜挂帅”“赛马机制”推动OPC场景创新落地，每年落地5个以上创新场景\n\n【人才服务】\n1.遴选支持AI领域顶尖创新人才创办OPC，提供创业导师辅导、产业空间、基金支持等；2.支持高校设置AI相关专业、“AI+创业”微专业，配备“技术+商业”双导师，每年培训人才1000名以上；3.累计引进培育OPC创业先锋1000人以上\n\n【投资融资】\n1.用好市级中小微企业融资增信基金、技术创新基金，落实创业担保贷款政策；2.鼓励各类产业引导基金投向OPC项目，建立尽职免责工作机制；3.推广小额信用贷、创业担保贷等信贷产品，常态化举办OPC路演会\n\n【其他】\n1.建立“种子级—成长级—领航级”梯度培育库，实施动态管理、分类指导；2.建立OPC信用评价体系，推行包容审慎监管模式，设置容错空间；3.完善适应OPC发展的社会保障制度，探索灵活就业人员参保新路径；4.每年举办OPC生态活动超100场','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资','https://www.qzfz.gov.cn/zwgk/zfxxgkzl/zfxxgkml/gzgzhgf/202604/t20260408_3281756.htm','https://www.qzfz.gov.cn/zcjd/bqzcjd/202604/t20260408_3281757.htm',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:07','2026-07-06 00:31:07'),(26,'《南昌高新区支持人工智能产业高质量发展若干政策措施（AI 十条）》',36,'南昌高新区管委会',NULL,'2026-03-24',NULL,'长期有效',25,'district','comprehensive','南昌高新区发布AI十条政策，聚焦人工智能产业发展，从技术攻关、平台建设、成果转化、要素保障等方面推出扶持举措，专门为AI一人公司（OPC）提供免费住宿、办公空间优惠等全周期支持。','政策要点：算力支持,资金补贴,场地工位,人才服务\n地区：江西省 / 南昌市 / 高新区','【算力支持】\n对企业算力、语料采购等研发投入按20％补贴，建设边缘智能算力最高补助100万元\n\n【资金补贴】\n1.对列入重点科技计划的AI核心技术攻关项目，按不超过上级拨付资金20％给予配套支持，单个项目最高补助500万元；2.对首台（套）重大技术装备、首版次软件产品，按不超过销售额10％补助，最高300万元；3.对优质公共服务平台最高补助80万元，符合条件额外最高奖励20万元；4.对通过国家备案的垂直大模型项目最高奖励50万元，关键技术突破项目最高补助300万元；5.对AI领域贷款给予最高50％利息补贴，年度最高50万元\n\n【场地工位】\n为AI领域一人公司（OPC）企业提供最长3个月免费住宿、24个月办公空间优惠，搭建创业孵化平台','算力支持,资金补贴,场地工位,人才服务','https://gxt.jiangxi.gov.cn/jxsgyhxxht/dsgx/content/content_2036257682931310592.html',NULL,NULL,'2026-07-04','draft','excel-import','2026-07-06 00:31:08','2026-07-06 00:31:08'),(27,'湖北省人民政府办公厅关于印发《湖北省支持人工智能OPC发展若干措施（试行）》的通知',42,'湖北省人民政府办公厅','鄂政办发〔2026〕10号','2026-05-15','2026-05-11','试行',26,'provincial','comprehensive','湖北出台试行政策扶持 AI 一人公司 OPC，覆盖算力、场地、人才、融资、场景、研发补贴，设置多档最高百万级补助，配套政务、知识产权一站式服务，全方位降低 AI 个体创业成本。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资\n地区：湖北省','【算力支持】\n1. 省级 2000 万元专项扶持 OPC 园区算力；2. 单家 OPC 免费 3000 元算力卡时 /token；3. 算力券按费用 30% 补贴，上限 10 万元；4. 上云券最高 10 万元；5. 科创券按服务费 30% 补贴，上限 20 万元；6. 可免费使用东湖大模型公共算力\n\n【资金补贴】\n1. 优质 OPC 生态社区最高 500 万元补助；2. 大学生 OPC 创业项目最高 50 万元扶持；3. 工业专用 AI 大模型研发按 8% 补助，最高 500 万元；4. 科创券、算力券、上云券多级资金补贴\n\n【场地工位】\n盘活闲置楼宇打造 OPC 生态社区，提供共享研发工位、灵活办公空间；青年人才最长 3 年免租住房或租房补贴，园区配套一站式创业服务\n\n【场景需求】\n1. 搭建省级场景创新平台，开放医疗、文旅、教育等公共场景；2. 定期发布场景机会清单，政府采购预留份额倾斜 OPC；3. 开放省级公共训练数据专区免费供给\n\n【人才服务】\n1. 高校增设 AI 交叉专业，校企共建创业实践基地；2. 青年人才享 3 年住房补贴、楚才卡 21 类便民服务；3. 支持 OPC 人才申报省级人才工程、评定 AI 专业职称\n\n【投资融资】\n1. 楚天凤鸣母基金单次最高 100 万元股权投资；2. 个人创业者最高 30 万、企业主体最高 500 万创业担保贷，财政贴息 50%；3. 推出算力贷专属产品，配套科技保险、融资担保增信\n\n【其他】\n1.OPC 开办 210 一站式零费用服务；2. 轻微违法容错免罚清单；3. 专利快速预审、法律服务、行业标准制定奖励；4. 支持 OPC 以知识产权作价入股、对接龙头企业外包需求','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资','https://www.hubei.gov.cn/zfwj/ezbf/202605/t20260515_5937376.shtml',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:09','2026-07-06 00:31:09'),(28,'市人民政府关于印发武汉市支持人工智能OPC创新发展若干措施的通知',42,'武汉市人民政府','武政规〔2026〕4号','2026-02-14','2026-03-18','至2028年12月31日',27,'city','comprehensive','武汉市出台全国首个副省级城市AI OPC专项政策，从算力、数据、模型、人才、社区、创业启动、线上社区、场景开放、金融支撑、氛围营造十大方面，构建全链条扶持体系，打造全国AI OPC创新发展高地。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资\n地区：湖北省 / 武汉市','【算力支持】\n1.设立算力服务券，对OPC当年算力服务费用的50％给予最高20万元补助，补助期限不超过3年；2.各区每年为每家OPC提供不少于2000卡时的免费算力支持；3.建设市级算力公共服务平台，优化算力供需匹配和交易流程\n\n【资金补贴】\n1.对OPC垂直领域模型研发按研发成本的30％给予最高500万元补助；2.对OPC大模型采购费用的50％给予最高100万元补助；3.对符合条件的OPC给予初创企业最高100万元的创业资助；4.对示范应用场景项目按总投入的30％给予最高100万元资金支持；5.对OPC生态社区最高给予500万元资金支持\n\n【场地工位】\n1.布局建设一批OPC生态社区，提供低成本办公空间、普惠算力等全链条服务；2.对入驻OPC提供最长2年的免费公共服务包，涵盖财务代账、税务申报、法律咨询等；3.提档升级“武汉青年人才之家”，为来汉创业OPC人才提供最长15天免费住宿；4.为OPC创业者提供2年每月不超过2000元的免租人才租赁房\n\n【场景需求】\n1.每年挖掘不少于100个OPC典型应用场景，发布“场景机会清单”“技术能力清单”；2.支持行业主管部门、企事业单位向OPC开放政务服务、教育、医疗、公共安全等应用场景；3.举办“武创荟”科技成果转化OPC专场活动，开展供需对接\n\n【人才服务】\n1.组织开展AI领域引才活动不少于50场，帮助OPC发布优薪优岗；2.对入选武汉英才计划的OPC人才，分别给予100万元、50万元、20万元资助；3.市属高校联合企业共建OPC创业实践基地，开展校企协同育人试点；4.对OPC创始人及高管在汉购买新建商品房，按每平方米1000元给予最高10万元购房补贴\n\n【投资融资】\n1.发挥政府种子基金作用，建立OPC投资绿色通道，用好“路演即投决”一体化机制；2.推出“算力贷”产品，单笔贷款最高1000万元，对贷款本金损失给予最高80％的风险补偿；3.为OPC创业者提供最高30万元、最长3年的创业担保贷款，10万元以下免除反担保要求；4.为OPC提供最高500万元、最长2年的创业担保贷款\n\n【其他】\n1.依托“武创通”科创服务平台打造OPC线上开放社区，融合技术交流、开源协同、工具集成、政策推送等功能；2.每年高水平举办OPC创新创业大赛，发掘不少于50个标杆项目；3.支持成立OPC创新创业联盟，常态化举办主题展会、高端论坛、创投沙龙等活动；4.建立大赛与市级人才计划直通机制，获奖团队核心成员优先推荐申报武汉英才计划','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资','https://www.wuhan.gov.cn/zwgk/xxgk/zfwj/gfxwj/202602/t20260214_2730572.shtml','https://www.wuhan.gov.cn/zwgk/xxgk/zcjd/bmjd/202606/t20260612_2776601.shtml',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:10','2026-07-06 00:31:10'),(29,'广东省发展改革委关于印发《广东省支持人工智能OPC创新发展行动方案（2026-2028年）》的通知',44,'广东省发展和改革委员会','粤发改高技〔2026〕78号','2026-03-17','2026-03-12','至2028年12月31日',28,'provincial','comprehensive','广东省出台全国首个省级AI OPC专项行动方案，2026-2028年分阶段推进，从基础能力保障、空间载体配套、场景开放创新、融资渠道拓宽、人才政策供给、服务保障体系六大方面，打造全国领先的AI OPC发展高地。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资\n地区：广东省','【算力支持】\n1.打造绿色协同算力“一张网”，建设粤港澳大湾区国家枢纽节点，提供跨区域弹性调度普惠算力；2.省市协同完善“算力券”制度，降低OPC算力支出成本；3.搭建智能算力公共服务平台，优化算力供需匹配和交易流程；4.建设人工智能OPC适用的公共模型服务平台，提供免费模型接口、安全合规检测等服务\n\n【资金补贴】\n1.在省重点领域研发计划AI专项中，支持模型轻量化、数据融合与标注等技术研究；2.鼓励有条件的地市对OPC模型开发投入给予补贴，对自主研发并完成备案的垂直领域模型，可叠加省级专项资金支持；3.举办广东省高质量数据集创新发展大赛，支持市场主体开发高质量语料库，有条件的地市可制定补贴政策\n\n【场地工位】\n1.鼓励各地布局建设OPC生态社区，提供低成本独立办公区、灵活共享工位、智能办公设备，实现“拎脑入驻”；2.开展省级OPC生态社区认定评估，对符合条件的给予算力补贴等支持；3.推动传统创新孵化器改造，重构空间布局，配备轻量化、共享式财务法务服务点\n\n【场景需求】\n1.构建OPC“场景池”，聚焦短剧短视频、电子商务、数字文创等重点领域，动态发布场景供需清单；2.依托粤港澳大湾区应用场景发布厅开展供需对接，推动OPC场景创新项目落地；3.拓展跨境特色应用场景，支持OPC开拓葡语国家、东南亚地区等海外市场，承接跨境电商、内容创作等领域跨境订单\n\n【人才服务】\n1.建立以创新能力、质量、实效、贡献为导向的OPC人才评价机制，将符合条件的OPC人才纳入广东省高层次人才认定范围；2.支持将港澳及海外OPC人才纳入人才引进绿色通道，提供便利化停居留、创业服务；3.鼓励高校、职业院校设置“人工智能+”交叉学科，校企共建高水平实验室和实训基地；4.实施大规模职业技能提升培训，开展AI技术技能专项提升行动，上线OPC专题课程资源；5.支持各地为OPC创业人才提供免租或低租人才公寓、创业驿站等安居支持\n\n【投资融资】\n1.发挥粤港澳大湾区国家创业投资引导基金、省战略性新兴产业投资引导基金等各类基金作用，重点投向OPC社区高成长性企业；2.支持银行业金融机构推出“人才贷、研发贷、成果贷、算力贷”等OPC专属信贷产品；3.鼓励保险公司开发“种子项目投资保”等产品，降低OPC早期研发活动风险\n\n【其他】\n1.推行OPC企业登记全流程智能办理，实现企业开办“一天办结、一网通办”；2.探索建立OPC领域包容审慎的柔性监管机制；3.为OPC算法、模型、数据集等提供知识产权保护，强化知识产权金融服务；4.在OPC社区设立区域性调解组织，打造聚焦OPC的特色法律服务团队；5.高水平建设国家人工智能应用中试基地，为OPC提供研发中试验证环境；6.举办OPC系列推介活动、创新创业大赛，发掘优质OPC创新主体','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资','https://www.gd.gov.cn/gdywdt/zwzt/rgznjqr/zcwj/content/post_4870549.html','https://www.gd.gov.cn/gdywdt/zwzt/rgznjqr/zcwj/content/post_4870556.html',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:10','2026-07-06 00:31:10'),(30,'广州海珠OPC创新发展十条',44,'广州市海珠区人民政府',NULL,'2026-03-19',NULL,'长期有效',29,'district','comprehensive','广州海珠区率先发布OPC创新发展十条，全国首创“4S”核心SOPC产业生态，从空间支持、算力补贴、场景开放、备案支持、政务人才服务等十大方面，为AI一人公司提供最高500万元支持。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务\n地区：广东省 / 广州市 / 海珠区','【算力支持】\n对OPC购买算力给予50%的补贴，年度上限20万元；对购买数据给予30%的补贴，年度上限10万元\n\n【资金补贴】\n1.对引领性OPC项目给予最高500万元支持；2.对完成国家级生成式AI服务算法备案的，最高支持100万元\n\n【场地工位】\n符合条件的OPC企业每年可享受最长12个月的工位费用减免\n\n【场景需求】\n聚焦医疗、交通、营销、游戏等领域开放场景，评选优质项目给予最高500万元支持\n\n【人才服务】\n出台“高端人才磁聚行动”扶持政策，提供全链条人才服务保障\n\n【其他】\n1.依托“一网通办”平台建立服务专区，提供工商注册、财税代理、资质办理、政策申报等全流程代办服务；2.全国首创以Smart、Solution、Save、Scene为核心的“4S”SOPC产业生态','算力支持,资金补贴,场地工位,场景需求,人才服务','https://www.gd.gov.cn/gdywdt/zwzt/jfqyhl/csjrzc/content/post_4872547.html',NULL,NULL,'2026-07-04','draft','excel-import','2026-07-06 00:31:11','2026-07-06 00:31:11'),(31,'香洲区大力培育OPC产业发展新模式行动方案',44,'珠海市香洲区人民政府',NULL,'2026-05-09','2026-05-09','至2028年12月31日',30,'district','comprehensive','香洲区出台OPC产业发展新模式行动方案，2028年目标OPC主体突破500家，从空间载体、创业扶持、算力支持、人才保障、场景开放、金融服务等十大方面，打造粤港澳大湾区OPC创业首选地。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资\n地区：广东省 / 珠海市 / 香洲区','【算力支持】\n1.对符合条件的OPC主体，购买算力服务按实际支出不超过50%予以“算力券”资助，每家每年不超过200万元；2.对购买大模型服务的OPC主体，按实际支出不超过30%予以“模型券”资助，每家每年不超过100万元\n\n【资金补贴】\n1.符合条件的OPC主体可申请1万元的一次性创业资助；2.每年遴选优质OPC创业项目，安排百万专项资金予以奖励；3.对港澳青年OPC主体，按规定给予15%的个税补贴；4.对港澳青年优秀创业项目，给予5万至50万元省级资助\n\n【场地工位】\n1.打造“香洲OPC创业港”，提供低成本办公空间、共享会议室、直播影棚等“拎包入驻”服务；2.OPC创业者可享受最长三年低成本共享工位使用支持，给予水电、网络及物业服务优惠；3.独立空间OPC可享受首年低成本使用优惠，租期届满可递延两年，租金按市场价50%扶持\n\n【场景需求】\n动态收集OPC场景能力清单，挖掘并释放不少于100个OPC典型应用场景，鼓励政府单位、国有企业采买OPC服务，开放人工智能“切片化”分包场景\n\n【人才服务】\n1.符合条件的OPC创业者，可获人才住房保障资格，享受三年租金优惠：首年免费，次年市场价30%，第三年50%；2.港澳青年OPC主体参加初创企业经营者能力提升培训，可获10000元/人资助；3.OPC创业者非香洲户籍子女入学、入园享受公办教育保障，统筹安排公办学位\n\n【投资融资】\n1.符合条件的OPC主体可申请最高60万元的贷款额度以及50%贷款贴息；2.建立OPC投融资路演和资本对接常态化机制，联动市、区产业基金、创投机构，重点支持早期AI驱动型、高成长型OPC项目；3.构建“基金+信贷+担保+贴息”综合金融支持体系\n\n【其他】\n1.由区属国企组建“OPC创业全生命周期服务中心”，提供财税法务、知识产权、AI合规、跨境合规等全链条咨询服务；2.实现工商、税务、社保、资质认定一网通办；3.经重点推荐的OPC创业者，可享受免费体检；4.全面落实小微企业、科技型企业及AI相关税收优惠政策，提供精准税务辅导','算力支持,资金补贴,场地工位,场景需求,人才服务,投资融资','https://www.zhxz.gov.cn/zfxxgk/zfxxgkml/content/post_3903356.html',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:11','2026-07-06 00:31:11'),(32,'《广州市番禺区支持OPC创业若干措施（征求意见稿）》',44,'广州市番禺区人民政府',NULL,'2026-03-22',NULL,'长期有效',31,'district','comprehensive','番禺区发布OPC创业扶持政策征求意见稿，全市首创OPC精准扶持政策，从开源AI智能体支持、人才服务、创业资金支持等方面，推动OPC支持从“普惠型”向“精准型”升级。','政策要点：资金补贴,人才服务\n地区：广东省 / 广州市 / 番禺区','【资金补贴】\n1.对向国际主流社区贡献关键代码、开发上架产业技能包、开发具身智能应用项目，经认定后给予最高100万元补贴；2.对开源AI智能体深度应用项目，按实际投入20%给予一次性最高50万元奖励；3.对入库的青年创新创业项目，给予最高5万元创新创业奖励、最高100万元研发资助\n\n【人才服务】\n1.支持符合条件的OPC人才申报番禺区高层次人才，对杰出贡献个人/团队分档给予最高500万元的人才发展补贴；2.对新引进在番禺区OPC企业全职工作的全日制博士，给予最高10万元落户补贴；3.对符合条件的引进单位，给予最高15万元引才补贴\n\n【其他】\n1.精准定义OPC新业态，分为模式创新型、场景应用型、生态服务型、其他类型四类主体；2.谋划设立青年创新创业项目库，精准扶持青年OPC创业项目','资金补贴,人才服务','https://www.gz.gov.cn/zwfw/zxfw/kjcy/content/post_10736196.html',NULL,NULL,'2026-07-04','draft','excel-import','2026-07-06 00:31:12','2026-07-06 00:31:12'),(33,'《中原区支持人工智能OPC创新发展若干措施(征求意见稿)》',41,'郑州市中原区人民政府',NULL,'2026-04-03',NULL,'长期有效',32,'district','comprehensive','中原区拟出台OPC创新发展十条举措，全省首个OPC专项政策，覆盖OPC注册、研发、运营、成长全生命周期，从人才补贴、创业扶持、梯度培育等方面，为AI一人公司提供全链条硬核支持。','政策要点：资金补贴,人才服务\n地区：河南省 / 郑州市 / 中原区','【算力支持】\n可叠加郑州市级算力券政策，对算力使用方给予不超过单个合同额20％的补助，同一企业每年不超过100万元\n\n【资金补贴】\n1.对毕业3年内来区工作的全日制博士、35岁以下硕士、本科及预备技师，每月发放1500元、1000元、500元生活补贴，补贴3年；2.对大中专学生首次创办企业，正常经营1年以上，给予一次性开业补贴1万元；3.对首次认定的人工智能标杆企业，给予一次性10万元的奖补；4.对首次认定、重新认定的高新技术企业分别给予最高20万元、5万元奖补；5.对入选国际国内权威榜单的独角兽、潜在独角兽AI企业，分别给予500万元、200万元的一次性奖补；6.对首次认定为专精特新“小巨人”企业、“隐形冠军”企业，分别给予100万元的奖补\n\n【人才服务】\n1.对毕业3年内来区工作的博士、硕士、本科等人才，发放3年生活补贴；2.高校毕业生自主创业的，可申请不超过50万元的创业担保贷款\n\n【投资融资】\n1.高校毕业生自主创业的，可申请不超过50万元的创业担保贷款；2.对高成长性OPC主体，提供全周期培育服务，安排专人提供政策解读、材料预审、全流程帮办等专属服务\n\n【其他】\n1.全省首个针对AI OPC的专项扶持政策，覆盖OPC全生命周期；2.梯度培育创新型企业，建立全周期培育服务体系；3.鼓励AI领军企业向中小企业开放资源，开展产业链协同创新','资金补贴,人才服务','https://www.zhongyuan.gov.cn/zyyw/9986182.jhtml','https://www.zhongyuan.gov.cn/zyyw/9986182.jhtml',NULL,'2026-07-04','draft','excel-import','2026-07-06 00:31:12','2026-07-06 00:31:12'),(34,'《郑东新区支持人工智能 OPC 创新发展若干措施》',41,'郑东新区管委会、中原科技城管委会','无','2026-04-12','2026-04-12','长期有效',33,'district','comprehensive','郑东新区中原科技城发布AI OPC专项扶持措施，打造中原数谷OPC生态社区，提供免费办公空间、算力仪器使用补助、专项股权投资、全链条生态配套服务，助力AI一人公司发展。','政策要点：算力支持,资金补贴,场地工位,投资融资,其他\n地区：河南省 / 郑州市 / 郑东新区','【算力支持】\n入驻OPC使用园区公共智算集群、AI科研仪器、大模型API调用，按实际支出给予阶梯补助，叠加郑州市级算力券，年度补贴上限100万元；依托曙光河南算力平台发放免费算力Token额度。\n\n【资金补贴】\n无直接现金补贴，以算力补贴、股权投资为主\n\n【场地工位】\n开放中原科技城科创大厦、中原数谷中国电子数据创新中心载体，提供长期免费共享办公工位、独立小型创作空间，配套一站式创业服务大厅。\n\n【场景需求】\n定期发布政企场景需求清单，开放数字经济、文创、软件开发、智能体开发落地场景\n\n【人才服务】\n为OPC核心创业者提供人才公寓、子女教育、政务绿色通道优待\n\n【投资融资】\n中原科技城产业基金设立OPC专项投资池，为优质AI一人公司项目提供股权投资；优先对接科技型知识价值信用贷、创业担保贷款，配套政府性融资担保、专属科技保险。\n\n【其他】\n组建河南省首个AI+OPC生态联盟，整合算力、数据、AI工具、市场渠道资源；常态化举办OPC项目路演、创业沙龙、AI技术培训、产需对接会。','算力支持,资金补贴,场地工位,投资融资,其他','https://vt.quark.cn/blm/quark-doc-main-pc-966/preview?fp_from=sc&id=5C27E31DE3DBED1FFDD001043AC96E03&sid=e237b0cea6394daca17ea2fa66e106bd',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:12','2026-07-06 00:31:12'),(35,'永州发布十条保障措施诚邀创业者',43,'永州市人民政府','无','2026-04-19','2026-04-19','长期有效',34,'city','comprehensive','永州出台OPC发展十条措施，打造OPC创客空间，提供12个月免费场地、免费云端算力、种子项目最高500万股权投资，配套开源社区融合发展扶持，助力AI一人公司落地。','政策要点：算力支持,资金补贴,场地工位,投资融资,其他\n地区：湖南省 / 永州市','【算力支持】\n为入驻OPC提供免费云端算力资源，配套开源社区算力支持\n\n【资金补贴】\nOPC种子项目最高500万元股权投资，配套创业扶持资金\n\n【场地工位】\n打造OPC创客空间，提供12个月免费办公场地、共享配套空间\n\n【场景需求】\n对接本地产业场景需求，提供开源社区项目落地场景\n\n【人才服务】\n配套创业导师指导、技术培训服务\n\n【投资融资】\n设立OPC专项种子基金，优质项目最高500万元股权投资，对接本地金融机构信贷支持\n\n【其他】\n支持OpenClaw等开源社区项目与OPC社区融合发展，提供开源技术支持、社区运营服务，常态化举办创业活动。','算力支持,资金补贴,场地工位,投资融资,其他','https://www.hunan.gov.cn/hnszf/hnyw/szdt/202604/t20260419_33958335.html','https://www.yzcity.gov.cn/cnyz/bmkx/202604/0e3c34efe69e43c8bc513dd543b3db63.shtml',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:13','2026-07-06 00:31:13'),(36,'长沙经济技术开发区管委会 关于印发《长沙经济技术开发区关于智能体和“一人公司”开源社区安全发展的十条措施》的通知',43,'长沙经济技术开发区管委会','无','2026-03-30','2026-03-30','长期有效',35,'district','comprehensive','长沙经开区出台智能体和一人公司开源社区发展十条措施，聚焦AI OPC安全发展，提供算力配套、场景对接、创业孵化、安全合规指导，助力AI一人公司健康发展。','政策要点：算力支持,场地工位,场景需求,其他\n地区：湖南省 / 长沙市 / 经济技术开发区','【算力支持】\n为入驻OPC提供园区算力资源配套，降低AI模型训练、推理算力成本\n\n【资金补贴】\n无直接现金补贴，以算力配套、孵化服务为主\n\n【场地工位】\n提供园区孵化场地支持，配套共享办公空间、公共服务设施\n\n【场景需求】\n对接园区制造业、智能网联汽车等产业场景需求，开放落地应用场景\n\n【人才服务】\n提供开源技术培训、安全合规指导、创业导师服务\n\n【投资融资】\n对接园区产业基金、金融机构，提供融资对接服务\n\n【其他】\n聚焦AI一人公司开源社区安全发展，提供合规指导、安全技术支持，打造安全可控的OPC发展生态。','算力支持,场地工位,场景需求,其他','http://cetz.changsha.gov.cn/zfxxgk/xxgk_43775/lzyj/gfxwj/ggwwj/202603/t20260330_12347657.html',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:14','2026-07-06 00:31:14'),(37,'济南启动城市级数智生态OPC社区，发布十项政策礼包',37,'济南市大数据局、济南市人民政府','无','2026-02-12','2026-02-12','长期有效',36,'city','comprehensive','济南启动城市级数智生态OPC社区，发布十项政策礼包，打造12个示范OPC社区，配套50亿AI产业基金、浪潮普惠算力补贴、创业人才购房优惠，助力AI一人公司发展。','政策要点：算力支持,资金补贴,场地工位,人才服务,投资融资,其他\n地区：山东省 / 济南市','【算力支持】\n对接浪潮集团普惠算力资源，为OPC提供算力补贴、优惠算力服务\n\n【资金补贴】\n配套50亿AI产业基金，为优质OPC项目提供股权投资、资金扶持\n\n【场地工位】\n打造12个示范OPC社区，提供共享免费工位、配套办公空间\n\n【场景需求】\n开放城市治理、工业、文创等应用场景，对接OPC落地需求\n\n【人才服务】\n为OPC创业人才提供购房优惠、人才配套服务\n\n【投资融资】\n设立AI产业专项基金，提供股权投资、信贷对接、融资担保服务\n\n【其他】\n打造城市级OPC生态体系，提供全链条创业孵化、产需对接、技术交流服务。','算力支持,资金补贴,场地工位,人才服务,投资融资,其他','http://www.shandong.gov.cn/art/2026/2/12/art_116200_705089.html',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:14','2026-07-06 00:31:14'),(38,'关于印发《海南省支持人工智能OPC创新发展的若干措施》的通知',46,'海南省工业和信息化厅、海南省发展和改革委员会、海南省财政厅、中共海南省委人才发展局','琼工信规〔2026〕3号','2026-05-18','2026-06-20','至2028年12月31日',37,'provincial','comprehensive','海南出台专项政策支持AI一人公司OPC发展，布局全省OPC生态社区，对优质社区最高800万一次性奖励，提供算力补贴、场地免租、人才扶持等全链条支持，2026年6月20日起施行。','政策要点：算力支持,资金补贴,场地工位,人才服务,其他\n地区：海南省','【算力支持】\n为OPC提供算力券补贴，按算力使用费用的一定比例给予补贴，配套普惠算力资源\n\n【资金补贴】\n对优质OPC生态社区给予最高800万元一次性建设补助；对OPC创业项目给予专项创业补贴、税收优惠\n\n【场地工位】\n全省布局OPC生态社区，提供免费/低价办公工位、共享空间，配套一站式创业服务\n\n【场景需求】\n开放海南自贸港相关产业场景、文旅、医疗等公共应用场景\n\n【人才服务】\n为OPC创业人才提供落户、住房补贴、子女教育、人才配套服务\n\n【投资融资】\n对接海南自贸港产业基金、金融机构，提供融资支持\n\n【其他】\n支持OPC参与自贸港数字经济建设，提供跨境数据、出海服务配套，打造国际化OPC发展生态。','算力支持,资金补贴,场地工位,人才服务,其他','https://iitb.hainan.gov.cn/iitb/bmwjjj/202605/653a0cff775144d7a84b8130822a7a43.shtml?ddtab=true','https://www.hainan.gov.cn/hainan/zmqjxsm/202605/a49bcfcf47b44ef9bd9f0e8e55e74cfb.shtml',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:15','2026-07-06 00:31:15'),(39,'关于印发《四川省支持人工智能OPC创新发展行动方案（2026—2027年）》的通知',51,'四川省科学技术厅、四川省人力资源和社会保障厅、四川省经济和信息化厅','无','2026-04-17','2026-04-17','至2027年12月31日',38,'provincial','comprehensive','四川出台OPC专项行动方案，目标2027年建成30个以上OPC生态社区、培育超千家AI一人公司，推出算力券、词元券、模型券补贴，提供拎脑入驻创业环境与人才配套支持。','政策要点：算力支持,资金补贴,场地工位,人才服务,其他\n地区：四川省','【算力支持】\n为OPC提供算力券、词元券、模型券补贴，降低AI模型训练、微调、API调用成本\n\n【资金补贴】\n对OPC生态社区建设给予资金支持，对优质OPC创业项目给予专项补贴\n\n【场地工位】\n全省布局OPC生态社区，提供拎脑入驻的免费办公工位、共享空间、配套服务\n\n【场景需求】\n开放四川数字经济、文创、工业、农业等应用场景，对接OPC落地需求\n\n【人才服务】\n为OPC创业人才提供落户、住房补贴、创业扶持、职称评定等配套服务\n\n【投资融资】\n对接四川省科技成果转化基金、金融机构，提供融资对接、信贷支持\n\n【其他】\n打造OPC创新创业生态，提供全链条孵化服务、技术培训、产需对接、行业交流活动。','算力支持,资金补贴,场地工位,人才服务,其他','https://kjt.sc.gov.cn/kjt/gstz/2026/4/17/454bbd76e963409a8193f9bcfc5af121.shtml?f_link_type=f_linkinlinenote&flow_extra=eyJkb2NfcG9zaXRpb24iOjAsImRvY19pZCI6ImI2ZGEwMGVlYmQyNDgyMzEtMDAyY2IwMzExMGU1NjVlYyIsImlubGluZV9kaXNwbGF5X3Bvc2l0aW9uIjowfQ%3D%3D',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:16','2026-07-06 00:31:16'),(40,'成都市打造人工智能OPC创新发展新高地行动计划（2026—2027 年）',51,'成都市经济和信息化局','无','2026-04-01','2026-04-01','至2027年12月31日',39,'city','comprehensive','成都出台OPC专项行动计划，目标2027年建成20个OPC社区，聚焦天府新区、高新区等区域布局，提供算力补贴、免费工位、人才扶持，打造AI一人公司创新发展新高地。','政策要点：算力支持,资金补贴,场地工位,人才服务,其他\n地区：四川省 / 成都市','【算力支持】\n为OPC提供算力补贴、普惠算力资源，降低AI算力使用成本\n\n【资金补贴】\n对OPC社区建设、优质OPC项目给予资金扶持、专项补贴\n\n【场地工位】\n在天府新区、高新区等区域布局OPC社区，提供免费办公工位、共享空间、配套服务\n\n【场景需求】\n开放成都文创、电子信息、智能制造等产业应用场景，对接OPC落地需求\n\n【人才服务】\n为OPC创业人才提供人才公寓、落户、子女教育、创业扶持等配套服务\n\n【投资融资】\n对接成都产业基金、金融机构，提供融资对接、信贷支持\n\n【其他】\n打造城市级OPC创新生态，提供全链条孵化服务、技术培训、产需对接活动。','算力支持,资金补贴,场地工位,人才服务,其他','https://cdjx.chengdu.gov.cn/cdsjxw/c132815/2026-04/01/27cb37ba12a94a5c8d17fb4028e79df2/files/17ef0c3dab8f41a68adfb5c8867cf8d1.pdf','https://www.chengdu.gov.cn/cdsrmzf/c174133/2026-03/25/content_1e6c12e4cd8d4bd1aca35d5dac711a82.shtml',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:17','2026-07-06 00:31:17'),(41,'遂宁市人工智能一人公司(OPC)培育发展行动方案(2026—2027年)',51,'遂宁市科学技术局、遂宁市数据局','遂科技[2026]27号','2026-06-10','2026-06-10','至2027年12月31日',40,'city','comprehensive','遂宁出台OPC培育方案，针对AI一人公司推出算力券、词元券、模型券补贴，重点群体最高1.5万创业补贴，毕业2年内高校毕业生房租补贴最高1000元/月，配套创业担保贷款。','政策要点：算力支持,资金补贴,场地工位,人才服务,投资融资,其他\n地区：四川省 / 遂宁市','【算力支持】\n为OPC提供算力券、词元券、模型券补贴，降低AI算力、模型使用成本\n\n【资金补贴】\n重点群体最高1.5万元创业补贴；毕业2年内高校毕业生房租补贴最高1000元/月\n\n【场地工位】\n提供OPC孵化场地支持，配套共享办公空间、创业服务设施\n\n【场景需求】\n对接遂宁电子信息、锂电、文旅等产业场景需求，开放应用场景\n\n【人才服务】\n为高校毕业生、青年创业者提供房租补贴、创业指导、技术培训服务\n\n【投资融资】\n为OPC提供创业担保贷款，配套贴息支持，对接本地金融机构\n\n【其他】\n提供OPC注册代办、财税咨询、知识产权等一站式创业服务，常态化举办创业活动。','算力支持,资金补贴,场地工位,人才服务,投资融资,其他','https://www.stdaily.com/web/gdxw/2026-06/11/content_530609.html',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:17','2026-07-06 00:31:17'),(42,'昆明市西山区OPC社区发展规划及专项扶持措施',53,'昆明市西山区人民政府、共青团西山区委','无','2026-04-14','2026-04-14','长期有效',41,'district','comprehensive','昆明西山区打造全省首个OPC社区，为AI一人公司提供零租金免费办公工位、一对一服务专员、免费算力Token资源、青创启航贷、导师陪跑等全链条扶持，实行1-2年阶梯式培育。','政策要点：算力支持,资金补贴,场地工位,投资融资,其他\n地区：云南省 / 昆明市 / 西山区','【算力支持】\n为入驻OPC提供免费算力Token资源，降低AI算力使用成本\n\n【资金补贴】\n提供创业扶持资金、青创启航贷等金融支持\n\n【场地工位】\n打造OPC社区，为AI一人公司提供零租金免费办公工位、共享空间、配套设施\n\n【场景需求】\n对接本地文旅、文创、数字经济等产业场景需求，开放应用场景\n\n【人才服务】\n提供一对一创业导师陪跑、技术培训、创业指导服务\n\n【投资融资】\n推出青创启航贷，为OPC提供低息信贷支持，对接本地金融机构\n\n【其他】\n实行1-2年阶梯式培育，提供注册代办、财税咨询、知识产权等一站式创业服务，打造云南首个OPC创业示范社区。','算力支持,资金补贴,场地工位,投资融资,其他','https://www.km.gov.cn/c/2026-04-14/5071108.shtml','https://m.kunming.cn/news/c/2026-03-30/14029388.shtml',NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:18','2026-07-06 00:31:18'),(43,'西宁市城中区OPC创业社区专项扶持政策',63,'西宁市城中区人民政府','无','2026-06-23','2026-06-23','长期有效',42,'district','comprehensive','西宁城中区打造OPC创业社区，为AI一人公司提供政策兑现绿色通道、创业导师一对一陪跑、AI智能创业服务模块、全链条创业孵化体系，已入驻企业3家。','政策要点：场地工位,人才服务,其他\n地区：青海省 / 西宁市 / 城中区','【算力支持】\n无专项算力补贴，配套本地算力资源对接服务\n\n【资金补贴】\n无直接现金补贴，以孵化服务、政策扶持为主\n\n【场地工位】\n打造OPC创业社区，提供办公场地、共享空间、配套孵化设施\n\n【场景需求】\n对接本地数字经济、文旅等产业场景需求，开放应用场景\n\n【人才服务】\n提供创业导师一对一陪跑、技术培训、创业指导服务\n\n【投资融资】\n对接本地金融机构，提供融资对接服务\n\n【其他】\n提供政策兑现绿色通道、AI智能创业服务模块、全链条创业孵化体系，配套注册代办、财税咨询等一站式服务。','场地工位,人才服务,其他','https://xncz.gov.cn/info/1005/221644.htm',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:19','2026-07-06 00:31:19'),(44,'青海省促进绿色算力产业发展若干措施',63,'青海省人民政府办公厅','青数〔2024〕11号','2024-03-23','2024-03-23','长期有效',43,'provincial','comprehensive','青海出台绿色算力产业发展措施，依托本地绿电资源，发展绿色算力产业，为AI企业提供绿色算力支持，配套算力建设、应用推广、产业培育扶持，无针对OPC一人公司的专项定向条款。','政策要点：算力支持,其他\n地区：青海省','【算力支持】\n为AI企业提供绿色算力资源，配套算力建设、应用推广扶持，降低算力使用成本\n\n【资金补贴】\n对绿色算力产业项目给予资金扶持、电价优惠\n\n【场地工位】\n无针对OPC的专项场地扶持\n\n【场景需求】\n开放绿色算力应用场景，推动AI算力在各行业的落地应用\n\n【人才服务】\n无针对OPC的专项人才扶持\n\n【投资融资】\n对算力产业项目给予融资支持，对接产业基金、金融机构\n\n【其他】\n依托青海绿电资源，打造全国绿色算力基地，为AI产业提供低碳算力支持，无针对AI一人公司OPC的专项定向扶持条款。','算力支持,其他','http://www.qinghai.gov.cn/zwgk/system/2024/03/23/030040009.shtml',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:20','2026-07-06 00:31:20'),(45,'北京市经济和信息化局关于印发《支持人工智能OPC创新发展行动方案（试行）》的通知',11,'北京市经济和信息化局','京经信发〔2026〕34号','2026-06-18','2026-06-18','长期有效',44,'provincial','comprehensive','北京出台市级OPC专项行动方案，支持OPC社区建设，最高给予200万元资金支持，为入驻OPC发放Token券、算力券、数据券，单个企业合计最高10万元，配套专属信贷产品“OPC贷”。','政策要点：算力支持,资金补贴,场地工位,投资融资,其他\n地区：北京市','【算力支持】\n为OPC发放Token券、算力券、数据券，单个企业合计最高10万元，降低AI算力、数据使用成本\n\n【资金补贴】\n对OPC社区建设最高给予200万元资金支持，对优质OPC项目给予专项补贴\n\n【场地工位】\n支持全市OPC社区建设，提供办公场地、共享空间、配套创业服务\n\n【场景需求】\n开放北京数字经济、文创、工业、政务等应用场景，对接OPC落地需求\n\n【人才服务】\n为OPC创业人才提供落户、人才配套服务\n\n【投资融资】\n推出专属信贷产品“OPC贷”，为OPC提供低息信贷支持，对接北京产业基金\n\n【其他】\n打造北京OPC创新发展生态，提供全链条孵化服务、技术培训、产需对接、行业交流活动。','算力支持,资金补贴,场地工位,投资融资,其他','https://www.beijing.gov.cn/zhengce/zhengcefagui/202606/t20260622_4710194.html',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:20','2026-07-06 00:31:20'),(46,'中关村科学城管理委员会关于印发《海淀区关于全面打造OPC创业生态的若干措施》的通知',11,'中关村科学城管理委员会','中科城发〔2026〕39号','2026-04-08','2026-04-08','1年',45,'district','comprehensive','海淀出台全国首个区级OPC系统性政策，为符合条件的新创OPC给予连续2年每年5万元创业资金支持，配套安居支持、算力补贴、赛事体系，有效期1年。','政策要点：算力支持,资金补贴,场地工位,人才服务,其他\n地区：北京市 / 海淀区','【算力支持】\n为OPC提供算力补贴，对接中关村算力资源，降低AI算力使用成本\n\n【资金补贴】\n为符合条件的新创OPC给予连续2年每年5万元创业资金支持；配套赛事奖金扶持\n\n【场地工位】\n打造OPC创业社区，提供免费办公工位、共享空间、配套服务\n\n【场景需求】\n开放中关村科学城产业场景需求，对接OPC落地应用\n\n【人才服务】\n为OPC创业人才提供安居支持、人才配套服务\n\n【投资融资】\n对接中关村产业基金、金融机构，提供融资支持\n\n【其他】\n打造全国首个区级OPC创业生态，提供全链条孵化服务、赛事体系、技术交流、产需对接活动。','算力支持,资金补贴,场地工位,人才服务,其他','https://zyk.bjhd.gov.cn/zwdt/zcwj/202604/t20260414_4811721.shtml',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:31:21','2026-07-06 00:31:21'),(47,'关于印发《朝阳区关于支持人工智能OPC创新发展的若干措施》的通知',11,'北京市朝阳区人民政府','无','2026-05-27','2026-05-27','长期有效',46,'district','comprehensive','朝阳出台OPC专项扶持政策，首批建成11个OPC社区，优质社区运营最高年补500万，OPC算力使用按50%给予补贴，每年最高50万元，场景项目最高支持500万元。','政策要点：算力支持,资金补贴,场地工位,场景需求,其他\n地区：北京市 / 朝阳区','【算力支持】\nOPC算力使用按50%给予补贴，每年最高50万元，降低AI算力使用成本\n\n【资金补贴】\n优质OPC社区运营最高年补500万元；场景落地项目最高支持500万元；优质OPC项目给予专项补贴\n\n【场地工位】\n首批建成11个OPC社区，提供免费办公工位、共享空间、配套创业服务\n\n【场景需求】\n开放朝阳区数字经济、文创、商务服务等应用场景，场景项目最高支持500万元\n\n【人才服务】\n为OPC创业人才提供人才配套服务\n\n【投资融资】\n对接朝阳区产业基金、金融机构，提供融资支持\n\n【其他】\n打造朝阳区OPC创新生态，提供全链条孵化服务、产需对接、技术交流活动。','算力支持,资金补贴,场地工位,场景需求,其他','http://www.bjchy.gov.cn/affair/file/otherfile/4028805a9dfdb457019e25a981de22c6.html','http://www.bjchy.gov.cn/slh/gsgg/4028805a9d486e5c019d6ae5e6fd19e7.html',NULL,'2026-07-04','published','excel-import','2026-07-06 00:39:46','2026-07-06 00:39:46'),(48,'关于印发《关于北京城市副中心支持数智创新OPC创新发展的若干措施》的通知',11,'中关村科技园区通州园管理委员会、北京市通州区政务服务和数据管理局、北京市通州区经济和信息化局、北京市通州区人才工作局','中通管文〔2026〕3号','2026-06-17','2026-06-17','长期有效',47,'district','comprehensive','通州副中心出台OPC专项措施，支持建设OPC生态友好社区，每年最高200万元资金支持，提供算力模型补贴、数据要素供给、一站式创业服务，打造数智OPC创业体系。','政策要点：算力支持,资金补贴,场地工位,其他\n地区：北京市 / 通州区','【算力支持】\n为OPC提供算力模型补贴，对接副中心算力资源，降低AI算力、模型使用成本\n\n【资金补贴】\n支持OPC生态友好社区建设，每年最高200万元资金支持；优质OPC项目给予专项补贴\n\n【场地工位】\n打造OPC生态社区，提供办公场地、共享空间、配套创业服务\n\n【场景需求】\n开放副中心政务、城市治理、数字经济等应用场景\n\n【人才服务】\n为OPC创业人才提供人才配套服务\n\n【投资融资】\n对接副中心产业基金、金融机构，提供融资支持\n\n【其他】\n提供数据要素供给、一站式创业服务、全链条孵化支持，打造北京城市副中心数智OPC创业体系。','算力支持,资金补贴,场地工位,其他','https://www.bjtzh.gov.cn/bjtz/xxfb/202606/1792736.shtml',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:39:46','2026-07-06 00:39:46'),(49,'关于支持打造 opc 超级个体社区的若干措施',31,'上海市杨浦区人民政府','杨府发〔2026〕4 号','2026-05-13','2026-05-13','长期有效',48,'district','comprehensive','杨浦出台全国首个区级 OPC 系统性政策，聚焦 AI 驱动的一人公司，提供人才引育、场地支持、算力补贴、场景对接全生命周期创孵服务，打造复兴岛全球创客岛 OPC 集聚地。','政策要点：算力支持,资金补贴,场地工位,场景需求,人才服务,其他\n地区：上海市 / 上海市 / 杨浦区','【算力支持】\n为OPC提供算力补贴，对接上海算力资源，降低AI算力使用成本\n\n【资金补贴】\n对OPC社区建设、优质OPC项目给予资金扶持、专项补贴\n\n【场地工位】\n打造复兴岛全球创客岛OPC集聚地，提供免费办公工位、共享空间、配套创业服务\n\n【场景需求】\n开放杨浦数字经济、文创、科技服务等应用场景，对接OPC落地需求\n\n【人才服务】\n为OPC创业人才提供人才引育、落户、住房补贴、创业扶持等配套服务\n\n【投资融资】\n对接杨浦产业基金、金融机构，提供融资对接、信贷支持\n\n【其他】\n打造全国首个区级OPC系统性扶持体系，提供全生命周期创孵服务、技术培训、产需对接、行业交流活动。','算力支持,资金补贴,场地工位,场景需求,人才服务,其他','https://www.shyp.gov.cn:443/zhengwu/qfb-zfwj/2026/135/2935/4c640240e9704e84b24740c1f9811c33.pdf','https://www.shanghai.gov.cn/gwk/search/content/00772935',NULL,'2026-07-04','published','excel-import','2026-07-06 00:39:47','2026-07-06 00:39:47'),(50,'武清区关于支持 OPC 创新发展的若干措施',12,'天津市武清区人民政府办公室','无','2026-06-17','2026-06-17','长期有效',49,'district','comprehensive','武清区出台 OPC 专项扶持措施，打造 OPC 生态社区，提供工商注册、税务登记等一站式创业服务，配套算力补贴、创业扶持、产业对接，助力 AI 一人公司孵化发展，打造区域 AI 超级个体孵化加速器。','政策要点：算力支持,资金补贴,场地工位,其他\n地区：天津市 / 天津市 / 武清区','【算力支持】\n为OPC提供算力补贴，对接天津算力资源，降低AI算力使用成本\n\n【资金补贴】\n对OPC生态社区建设、优质OPC项目给予创业扶持资金\n\n【场地工位】\n打造OPC生态社区，提供办公场地、共享空间、配套创业服务\n\n【场景需求】\n对接武清区产业场景需求，开放应用场景\n\n【人才服务】\n提供创业指导、技术培训服务\n\n【投资融资】\n对接武清区产业基金、金融机构，提供融资支持\n\n【其他】\n提供工商注册、税务登记等一站式创业服务，打造区域AI超级个体孵化加速器，常态化举办创业活动。','算力支持,资金补贴,场地工位,其他','https://www.tjwq.gov.cn/zwgk/zcwj/wqqzc/zfb/202606/t20260617_7319340.html','无',NULL,'2026-07-04','published','excel-import','2026-07-06 00:39:47','2026-07-06 00:39:47'),(51,'天津滨海高新区支持人工智能 OPC 创新发展若干措施',12,'天津滨海高新技术产业开发区管委会','无','2026-03-27','2026-03-27','征求意见中',50,'district','comprehensive','滨海高新区发布 OPC 专项措施征求意见稿，打造 AI 智能体创新社区，入驻 OPC 最长 12 个月办公场地优惠，免除工商注册及首年代账费用，算力调用费用 30% 补贴，年度最高 30 万元，配套专属信贷产品。','政策要点：算力支持,资金补贴,场地工位,投资融资,其他\n地区：天津市 / 天津市 / 滨海高新区','【算力支持】\nOPC算力调用费用给予30%补贴，年度最高30万元，降低AI算力使用成本\n\n【资金补贴】\n免除OPC工商注册及首年代账费用，提供创业扶持资金\n\n【场地工位】\n打造AI智能体创新社区，入驻OPC最长12个月办公场地优惠，提供共享办公空间\n\n【场景需求】\n对接滨海高新区产业场景需求，开放智能体、AI应用落地场景\n\n【人才服务】\n提供创业指导、技术培训服务\n\n【投资融资】\n推出OPC专属信贷产品，对接高新区产业基金、金融机构，提供融资支持\n\n【其他】\n提供一站式创业服务，打造AI智能体创新社区，助力AI一人公司孵化发展。','算力支持,资金补贴,场地工位,投资融资,其他','https://www.tjbh.gov.cn/contents/12166/601977.html',NULL,NULL,'2026-07-04','draft','excel-import','2026-07-06 00:39:48','2026-07-06 00:39:48'),(52,'关于印发《重庆市迭代推进“满天星”行动计划打造“未来星”OPC创业生态工作方案》的通知',50,'重庆市经济和信息化委员会','渝满天星专班办〔2026〕2号','2026-04-14','2026-04-14','至2027年12月31日',51,'provincial','comprehensive','重庆出台市级 OPC 专项工作方案，推出十条扶持措施，目标打造西部 AI OPC 创业首选地，统筹专项资金支持 OPC 社区建设，提供算力、模型、数据、场景全链条支持，实现 OPC 零成本开办。','政策要点：算力支持,资金补贴,场地工位,场景需求,其他\n地区：重庆市','【算力支持】\n为OPC提供算力、模型、数据资源支持，降低AI使用成本\n\n【资金补贴】\n统筹专项资金支持OPC社区建设，对优质OPC项目给予专项补贴\n\n【场地工位】\n全市布局OPC生态社区，提供免费办公工位、共享空间、配套服务，实现OPC零成本开办\n\n【场景需求】\n开放重庆数字经济、工业、文创等应用场景，对接OPC落地需求\n\n【人才服务】\n为OPC创业人才提供人才配套服务\n\n【投资融资】\n对接重庆产业基金、金融机构，提供融资支持\n\n【其他】\n目标打造西部AI OPC创业首选地，提供全链条创业孵化服务、技术培训、产需对接活动。','算力支持,资金补贴,场地工位,场景需求,其他','https://www.cq.gov.cn/index/detail.html?policyId=5656',NULL,NULL,'2026-07-04','published','excel-import','2026-07-06 00:39:48','2026-07-06 00:39:48');
