  KEY `idx_regions_level` (`level`),
  KEY `idx_regions_sort_order` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=83 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='地区表';
