CREATE TABLE `tags` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Tag name',
  `tag_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'policy/case/common',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT 'Sort order',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Created time',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Updated time',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tags_name_type` (`name`,`tag_type`),
  KEY `idx_tags_tag_type` (`tag_type`),
  KEY `idx_tags_sort_order` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=836 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tag dictionary table';
